INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699559100', 'Kit 6 Porta Guardanapo Porta Sachê e Colher 4 Divisões Plástico Resistente Lanchonete Restaurante', 'Organização e praticidade para o seu cantinho do café, lanchonete ou restaurante! O Porta Guardanapo com Divisórias para Sachês e Colheres é a solução ideal para manter sua mesa sempre arrumada e funcional. Com design compacto e 4 divisórias, ele acomoda guardanapos, sachês de açúcar, adoçantes, palitos e colheres de maneira prática e higiênica. ✅ Destaques do Produto: 4 Compartimentos: Divisórias independentes para organizar diversos itens do dia a dia com facilidade. Design Compacto e Funcional: Ideal para ambientes com pouco espaço como cantinhos do café, mesas de escritório, bancadas de cozinha ou balcões de atendimento. Material Resistente: Fabricado em plástico de alta qualidade, fácil de limpar e com excelente durabilidade. Estilo e Versatilidade: Combina com qualquer decoração e pode ser usado em cafeterias, padarias, buffets, restaurantes ou até mesmo em festas e eventos. Transforme a experiência de servir com mais organização e beleza. O Porta Guardanapo Sachê com Colher é prático, acessível e valoriza qualquer ambiente!', 169.9, 149.9, NULL, 'Home & Living > Home Organizers > Tissue Holders', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m968c6ncpsle6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316557325%2F18699559100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9598925633', '1kg Eletrodo 6013 de 3,25mm Serralheiro - Soldaforte', 'DESCRIÇÃO: O eletrodo 6013 3,25mm, é para quem busca um trabalho mais limpo com um nível de detalhamento maior, por ser mais fino ele proporciona facilidade na soldagem podendo alcançar locais de difícil acesso. Destinado para utilização em qualquer tipo de aço de construção e soldagens. Se caracteriza pela sua boa fluidez, excelente acabamento e fácil remoção da escória, podendo ser feito em todas as posições com uma excelente performance. ESPECIFICAÇÕES TÉCNICAS: :: Marca: SOLDAFORTE :: Modelo: 6013 - 3,25MM SERRALHEIRO :: Corrente (A): 50 - 70 :: Polaridade: CC(+) ou CA ATENÇÃO: :: Quantidade aproximada de eletrodos em 1kg: 29 eletrodos Devido a divergência de peso unitário de cada vareta, seguimos com a quantidade aproximada. PESO E DIMENSÕES: :: Peso: 1,0 kg :: Altura: 2,0 mm :: Largura: 2,0 mm :: Comprimento: 43,0 cm INCLUI: :: 1 (KG) Eletrodo Serralheiro 6013 3,25mm Soldaforte (aproximadamente 29 eletrodos) GARANTIA: :: Sem garantia. INFORMAÇÕES DE ENTREGA: :: Todos os produtos serão enviados de acordo com a forma escolhida pelo cliente, depois da confirmação do pagamento. Produtos comprados de segunda à sexta-feira até 12h serão postados no mesmo dia. O prazo para a entrega varia de acordo com a forma de envio escolhida, pode ser frete expresso, Pac, Sedex, então fique atento as condições de entrega da sua compra. Logo após a confirmação de postagem, você receberá todas as atualizações do status do seu pedido quanto o código de rastreio, direto pela plataforma. E atenção, lembre-se sempre de ter alguém para receber a sua compra, no endereço informado, para evitar que essa mercadoria seja devolvida.', 28.0, 28.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mazlynlmum0p57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341202873%2F9598925633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
