INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394545158', 'WHISKY JOHNNIE WALKER GREEN LABEL 15 750', 'Johnnie Walker Green Label é um blend escocês composto por quatro single malts de renomes sendo Talisker, Linkwood, Cragganmore e Caol Ila. Johnnie Walker Green Label é um whisky excepcional, uma homenagem à produção artesanal dos melhores blends escocês. O desafio de Johnnie Walker Green Label é proporcionar uma experiência única com maltes amadurecidos durante 15 anos, assegurando que os sabores realmente complementam-se mutuamente e trabalham em harmonia para criar uma mistura de grande complexidade, que na sua essência é fiel ao estilo Johnnie Walker de sabores grandes e com a sua assinatura. Origem: Escócia Graduação: 43% vol. Volume: 750 ml.', 679.99, 499.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-8259m-mfy5ffueio0bf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22394545158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
