INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693184562', 'Kit Cabo Vela Fiat Uno 1.3 Alcool 1985 A 1989', 'Dê Vida Nova ao Seu Fiat Prêmio: Desempenho e Confiança ao Seu Alcance! Está sentindo que seu Fiat Prêmio não responde como antes? A Gauss tem a solução ideal para você! A Importância de um Sistema de Ignição Impecável O sistema de ignição é o coração do seu motor. Cabos e velas de ignição desgastados podem causar falhas na partida, perda de potência, aumento no consumo de combustível e emissão de poluentes. Um sistema de ignição em perfeito estado garante um desempenho otimizado, economia e segurança para você e seu veículo. Gauss: Sinônimo de Qualidade e Durabilidade Com o Kit Cabo + Vela de Ignição Gauss, você garante a qualidade e a durabilidade que seu carro merece. A Gauss é referência no mercado automotivo, oferecendo produtos de alta performance e confiabilidade, testados e aprovados para superar suas expectativas. Invista na tranquilidade de saber que você está utilizando o melhor para o seu Fiat! Aplicação Precisa para o Seu Fiat Prêmio Este kit é a escolha certa para os seguintes modelos Fiat Prêmio: Fiat Prêmio (Motor SEVEL): 1985, 1986, 1987, 1988 Fiat Prêmio (Motor FIASA): 1985, 1986, 1987, 1988, 1989, 1992, 1993, 1994 Informações Importantes GTIN: 7899751924078 Dimensões da embalagem: 16 cm (altura) x 20 cm (largura) x 9 cm (profundidade) Peso: 0.572 kg Não Perca Tempo! Garanta agora mesmo o Kit Cabo + Vela de Ignição Gauss para o seu Fiat Prêmio e redescubra o prazer de dirigir com um motor potente e eficiente.', 140.53, 140.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kj60b6ypbm64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F22693184562', NULL, NULL