INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099906860', 'Motor Defrost para Brastemp BRM36 3000 RPM Hulter HT3MDBR220P - 220V', 'Motor Defrost para Brastemp BRM36 3000 RPM Hulter HT3MDBR220P - 220VO Motor Defrost para Brastemp BRM36 3000 RPM Hulter HT3MDBR220P - 220V é a escolha ideal para garantir o bom funcionamento do sistema de degelo da sua geladeira, proporcionando eficiência e confiabilidade no desempenho. Desenvolvido para operar com velocidade de 3000 rotações por minuto, ele assegura a circulação adequada do ar e o degelo uniforme, evitando o acúmulo de gelo no evaporador e mantendo a refrigeração sempre estável. Fabricado com materiais de alta qualidade, o motor oferece excelente durabilidade e resistência, suportando longos períodos de funcionamento contínuo sem perda de desempenho. Seu design compacto e compatibilidade com o modelo Brastemp BRM36 garantem uma substituição fácil e precisa, contribuindo para a conservação dos alimentos e o funcionamento eficiente do sistema de refrigeração. Com tensão de 220V e garantia de 3 meses, o Motor Defrost Hulter HT3MDBR220P é uma solução prática e confiável para quem busca restaurar ou manter o desempenho ideal da geladeira Brastemp.', 46.9, 46.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82580-mfvlrjzi7h1od3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21099906860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493174338', 'Buzina Automotiva Caracol Renault Duster 2015-2020 12v Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Buzina Automotiva Caracol Renault Duster 2015-2020 12v Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Renault Duster Buzina Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Renault Duster 2015 Renault Duster 2016 Renault Duster 2017 Renault Duster 2018 Renault Duster 2019 Renault Duster 2020 Especificações Técnicas do Veículo: Veículo: Duster Montadora: Renault Ano: 2015 a 2020 Especificação Técnica - Buzina: Cod Produto: Gb1052 Modelo: Buzina Caracol Voltagem: 12.0 Nivel Sonoro: 110.0 Quantidade De Conectores: 2.0 Quantidade Buzinas: 1.0 Quandidade De Cornetas: 1.0 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 46.99, 46.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5ki8v432awi67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23493174338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
