INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203041049', 'Coxim Cambio Ford Ka 1.0 Flex 2015 2016 2017', 'Somos concessionária autorizada Ford e trabalhamos exclusivamente com peças genuínas. Todas as peças são novas, originais de fábrica, acompanham nota fiscal e possuem garantia. Compre com segurança, procedência garantida e atendimento especializado. Por se tratar de peça original Ford, eventuais atendimentos de garantia podem ser realizados em qualquer concessionária autorizada Ford do Brasil, conforme as condições do fabricante. ITENS INCLUSOS: 1 coxim do câmbio; VEÍCULOS COMPATÍVEIS: Ford: • Ka 2015 1.0 TI-VCT • Ka 2016 1.0 TI-VCT • Ka 2017 1.0 TI-VCT • Ka 2018 1.0 TI-VCT PRINCIPAIS BENEFÍCIOS: Absorção de vibrações; Redução de ruídos; Maior durabilidade; Fácil instalação; DESCRIÇÃO: COXIM DA CAIXA DE MUDANCAS FORD. COD: E3B17M121AD APLICACAO: - FORD KA SEDAN COM MOTOR 1.0L TIVCT 12V FLEX (ALCOOL/GASOLINA) 21/07/2014 HA 08/07/2018 - FORD KA HATCH COM MOTOR 1.0L TIVCT 12V FLEX (ALCOOL/GASOLINA) 21/07/2014 HA 08/ GARANTIA: 3 meses Antes de realizar a compra, verifique cuidadosamente se a peça é compatível com o seu veículo, considerando modelo, ano e versão. Em caso de dúvida, utilize o campo de perguntas e, se desejar, envie o número do chassi. Nossa equipe poderá consultar e confirmar a compatibilidade da peça com o seu veículo antes da compra.', 289.11, 289.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mjahxnvmsykk95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676459102%2F58203041049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
