INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297671215', 'Regulador De Voltagem 14v Original Gauss Chevrolet Chevette', 'Mantenha a Energia do seu Clássico Chevrolet com o Regulador de Voltagem Gauss! Está na hora de dar a atenção que seu Chevrolet merece? Apresentamos o Regulador de Voltagem 14V Gauss, a peça que garante a estabilidade elétrica do seu veículo, protegendo seus componentes e assegurando o melhor desempenho. O regulador de voltagem é um componente crucial para o sistema elétrico do seu carro. Ele mantém a voltagem da bateria estável, evitando picos e quedas que podem danificar outros componentes eletrônicos. Garanta o bom funcionamento e a longevidade do sistema elétrico do seu veículo. Por que escolher Gauss? A Gauss é sinônimo de qualidade e confiabilidade no mercado automotivo. Com tecnologia de ponta e rigorosos testes de qualidade, os reguladores de voltagem Gauss são projetados para oferecer o máximo de performance e durabilidade, superando as expectativas dos clientes mais exigentes. Aplicação / Compatibilidade Este regulador de voltagem é compatível com os seguintes veículos Chevrolet: Chevette: 1974 a 1995 (Diversos motores) Kadett: 1989 a 1998 (Diversos motores) Monza: 1983 a 1998 (Diversos motores) Opala: 1971 a 1992 (Diversos motores) Especificações Técnicas Voltagem: 14V Amperagem: 65 A Códigos Equivalentes: 130666 (CARGO), 94648534 (DELCO REMY), D673 (GM ORIGINAL), RT510109 (MAGNETI MARELLI), VR-D671C (MOBILETRON), D671 (REGITAR), DE609 (TRANSPO) Não perca tempo! Adquira agora mesmo o seu Regulador de Voltagem 14V Gauss e garanta a segurança e o desempenho do seu Chevrolet. Clique e compre já!', 68.99, 68.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5kpe18wzekl95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23297671215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18775453304', 'Panela Elétrica Britânia Multifunções 3,5L Redstone BPE06', 'A Panela Elétrica Britânia Multifunções BPE06 Redstone vai deixar a hora de cozinhar muito mais fácil e prazerosa! Com ela você frita, cozinha, aquece, assa, tosta, gratina, grelha e refoga. Revestida com cerâmica Redstone, a Panela Elétrica BPE06 é mais saudável, durável, resistente e fácil de lavar, além de preservar o sabor e os nutrientes dos alimentos. Seu seletor de temperatura é removível e os pegadores são de toque frio, possibilitando que a panela seja levada à mesa. Com capacidade para 3,5L e tampa de vidro, é possivel acompanhar o preparo dos alimentos sem se preocupar com respingos pela bancada. Design moderno, eficiência e beleza para sua cozinha. Conte com a Panela Elétrica Britânia Multifunções BPE06 Redstone. Prepara diversos tipos de alimentos Panela com revestimento antiaderente cerâmico “Redstone” Seletor de temperatura removível Revestimento livre de PFOA, PTFE e PFOS Tampa de vidro temperado Alças laterais c/ toque frio Base antiderrapante Volume útil: 3 litros Volume máximo: 3,5 litros Luz indicadora de funcionamento', 309.9, 309.9, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mqz8ywzmiln0bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F18775453304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
