INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293105519', 'Kit 2 Pares de Meia Kendall 3/4 Média Compressão 1871', 'DESCRIÇÃO: Kit com 2 pares de meias medicinais Kendall Média Compressão 18-21mmHg. São indicadas para prevenção e tratamento dos diferentes estágios de doenças venosas, como varizes, doenças linfáticas, inchaços e cansaço nas pernas, pois possuem compressão graduada que garantem maior compressão no tornozelo e um decréscimo gradual até a altura da coxa (dependendo do modelo), facilitando a circulação sanguínea. Para quem sente dores acentuadas no final do dia. A Kendall, pioneira na aplicação de bacteriostático em seu produto, foi buscar novas tecnologias para proporcionar a você um conforto ainda maior. A Tecnologia UltraPro, além de adaptar-se a temperatura aumentando e diminuindo a sensação de frescor dependendo do ambiente e atividades, é um agente bacteriostático que age evitando o crescimento de microrganismos como bactérias e fungos causadores de odores desagradáveis nos artigos têxteis, proporcionando uma proteção duradoura e higiênica, conferindo a sensação de bem-estar e comodidade. Benefícios adicionais na sua meia Kendall®: Máxima proteção contra fungos e bactérias Prevenção de odores desagradáveis Frescor e Conforto Absorve a umidade da sua pele Regula a sensação térmica. COMPOSIÇÃO: 83% Poliamida e 17% Elastano. PAÍS DE ORIGEM: Brasil. INSTRUÇÃO DE LAVAGEM: Lavagem a mão/Temperatura máxima 40°C não alvejar não secar em tambor secagem em varal por gotejamento à sombra não passar não limpar a seco. INDICAÇÃO: Tratamento de varizes – Casos acentuados de Inchaço, dores e cansaço nas pernas – Uso de pílulas anticoncepcionais – Tendência hereditária e varizes – Viagem de longa distância, prevenindo a síndrome da classe econômica – Para quem fica o Dia inteiro sentado ou em pé – Durante ou após a gravidez. CONTRAINDICAÇÕES: Insuficiência arterial. Gangrena. Infecções cutâneas, Enxertia de pele em processo de cicatrização nos membros inferiores. CONTÉM:02 pares.', 195.9, 195.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rdyp-lyyjkd9z4siqa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421856066%2F22293105519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
