INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21448134843', 'Jogo Calha de Chuva Celta 00 a 16 Prisma 06 a 12 4p', 'MOTORPAN SHOP - Com mais de 30 anos de experiência no ramo automotivo e 3 anos no mercado digital de autopeças. TRABALHAMOS COM frisos, calhas de chuva, molduras e guias de para-choque, lanternas, grades, emblemas, cabos, amortecedor de tampa traseira e muito mais. Aplicação: • CHEVROLET CELTA 4 PORTAS 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 • CHEVROLET PRISMA 4 PORTAS 2006 2007 2008 2009 2010 2011 2012 2013 Especificações Técnicas: • Fabricado em 100% acrílico fumê de alta resistência • Fácil a instalação não necessita de furos ou adaptação • Produzida sob medida para o veículo • Ficção feita por fita dupla face 3M Conteúdo da Embalagem: • 2 Calhas de chuva Dianteiras • 2 Calhas de chuva Traseiras • 1 Primer(Promotor de aderência) - Instruções de instalação. 1. Aproxime o defletor do veiculo visualizando a área de colocação. 2. Antes da colocação, limpe a superfície com pano umedecido. 3. Aplique o primer com algodão ou estopa. 4. Descole e dobre as pontas do liner protetor para ajustar o defletor 5. Acomode o defletor começando sempre da base do retrovisor 6. Cole inicialmente as extremidades, puxe o liner protetor fixando a dupla-face na lataria. 7. Pressione a região da fita com flanela para tirar as bolhas de ar da fita.', 126.69, 117.83, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Deflectors', 'https://cf.shopee.com.br/file/d5b9e4688fcc1186012becc7f33c546a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F697113195%2F21448134843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
