INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26478672451', 'Kit Livros de colorir - Comfy & Cute', 'Kit Livros de colorir - Comfy & Cute Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok, é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante. Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas com 24 ilustrações exclusivas retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia. ISBN: 9786526121801 Cozy and Biblical - Livro de Colorir ISBN: 9786526121771 Comfy and Biblical - Livro de Colorir ISBN: 9786526122440 Fuzzy and Cute - Para Colorir ISBN: 9786526122921 Jungle Buddies - Livro de Colorir Dimensões: L 24.00 x A 24.00 x E 0.57', 99.6, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m711q2visegg1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26478672451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397786440', 'Livro Em volta do fogo as histórias são contadas', 'Em volta do fogo as histórias são contadas é uma coletânea de narrativas que, por meio de uma abordagem cuidadosa e envolvente, apresenta 21 etnias indígenas do Brasil, resgata suas histórias tradicionais e compartilha a riqueza cultural desses povos. Neste livro, Eraldo Miranda conduz os leitores por uma fascinante jornada pela diversidade e profundidade dos saberes ancestrais dessas comunidades, revelando suas tradições únicas. Mais do que uma simples coleção de narrativas, este livro é um convite para explorar e valorizar a cultura indígena brasileira, enriquecendo nossa compreensão da história e identidade do nosso país._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2024_x000D_ Autor: Eraldo Miranda_x000D_ Ilustrador: Vicente Mendonça_x000D_ Idioma: Português_x000D_ Páginas: 96_x000D_ Dimensões: L 20.10 x A 26.80 x E 0.10_x000D_ ISBN: 9786553844322_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 12 anos_x000D_ Assuntos (tags): Indígena, Brasil, Cultura indígena, Literatura brasileira , Lendas, Contos desconhecidos, Povos originários_x000D_ BISAC: Literatura Juvenil / Lendas, Mitos, Fábulas_x000D_ Linha de Produto: Ciranda Jovem_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-lz9c2gu4jcmidd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21397786440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293212680', 'Kit Fitness |Bolsa termica + Garrafa + Marmita Lunch Box + Talher BPA Free 30% trigo | Jacki Design', '✨ Kit completo para quem ama uma vida saudável e fitness, sem deixar estilo de lado! Esse conjunto da Jacki Design acompanha Garrafa + Marmita (ambos feitos com 30% de trigo e livre de BPA ) + Bolsa térmica com multicamadas de alumínio e elástico interno para segurar itens menores, perfeito para trabalho, estudos, passeios ou viagens. 💗 Estiloso, delicado e super funcional! 📦 O QUE VEM NO KIT: * 01 Garrafa para 300ml * 01 Marmita 800ml + Talher * Bolsa térmica com elástico interno 📐 MEDIDAS: Marmita com 800 ml: Altura: 9 cm Largura: 19 cm Profundidade: 13 cm Garrafa com 300 ml: Altura: 17 cm Largura: 7,2 cm Profundidade: 7,2 cm Bolsa Térmica com 2 tipos de alça: Largura: 35 cm Altura: 23 cm Profundidade: 12 cm 💎 DETALHES: * Garrafa livre de BPA para 300ml * Marmita livre de BPA para 800ml * Bolsa térmica possui um elástico interno para segurar garrafa ou itens menores, 2 tipos de alça (transversal ajustável e alças de mão) * Fácil de limpar * Estampa exclusiva * Produto original Jacki Design 🚚 Envio rápido e bem embalado!', 149.9, 134.2, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-820lk-mp3sv31ih0qrcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F22293212680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15297221757', 'Livro Literatura infantil Tulu no Sítio do Picapau Amarelo', 'Tulu deixou a floresta e foi a um sítio muito conhecido de todas as crianças: O Sítio do Picapau Amarelo. O que será que ele vai fazer lá? Quem estará esperando por ele? Um delicioso encontro de Tulu, personagem criado por Donaldo Buchweitz, com os famosos personagens de Monteiro Lobato._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Donaldo Buchweitz_x000D_ Ilustrador: Simone Ziasch_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 26.00 x E 0.30_x000D_ ISBN: 9786526102503_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda Cultural - Ficção infantil_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Natureza, Indígena, Literatura brasileira , Aventura, Diversão_x000D_ BISAC: Literatura Infantil / Natureza & Mundo Natural / Meio Ambiente_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvf4-lfljxqe58gjp73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F15297221757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
