INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794352123', 'Hidratante Corporal Nivea Milk Pele Extra Seca 400ml', 'Características do Produto: Marca: Nivea Sessão: Hidratante Uma unidade de embalagem contém 400ml Precauções: Uso externo. Não é indicado para uso no rosto. Não é protetor solar. Em caso de irritação, suspenda o uso e procure orientação médica. Manter em local seco e arejado, ao abrigo de luz e fora do alcance de crianças. Este é um produto cosmético, não ingerir. Modo de Usar: Aplique o produto massageando a pele até ser absorvido. Indicado para joelhos, pés, calcanhares e regiões mais ressecadas. Use todos os dias. Fornecedor - Nivea', 34.66, 34.66, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hr-mpib03dxowlne8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22794352123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
