INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54305870760', '3 Uni Granulado Granulé Chocolate ao Leite Melken 400g Harald', 'O Granulado Granulé Melken ao Leite é um produto premium desenvolvido especialmente para acabamento de doces e sobremesas, trazendo sofisticação, textura e sabor irresistível. Composto por chocolate ao leite verdadeiro, ele apresenta pequenos granulados brilhantes, com textura crocante e um derretimento suave na boca, ideal para dar acabamento perfeito a bombons, trufas, brigadeiros gourmet, bolos e outras criações de confeitaria. Peso Líquido: 400g / unidade Ingredientes: Açúcar, massa de cacau, manteiga de cacau, gordura vegetal, leite desnatado em pó, leite integral em pó, soro de leite, emulsificantes INS 322 e INS 476, aromatizante e glaceante INS 904. Não contém glúten. Contém lactose. Alérgicos: Contém derivados de soja e de leite. INFORMAÇÃO NUTRICIONAL - Porção de 25g Valor Energético: 134kcal=561kj. Carboidratos: 15g. Proteínas: 1,9g. Gorduras Totais: 7,8g. Gorduras Saturadas: 4,8g. Gorduras Trans: 0. Fibra Alimentar: 0,7g. Sódio: 22mg.', 209.36, 209.36, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkcrqncwa7eq37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F54305870760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
