INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27439759079', 'Mixsoon PDRN Collagen Eye Serum 20mL', 'Mixsoon PDRN Collagen Eye Serum 20mL An eye serum that is moisturizes and nourishes the delicate skin under eyes and help reduce the appearance of fine lines and wrinkles. Formulated with plant-based PDRN derived from rice to nourish and stregthen skin barrier. Contains Low Molecular Weight Collagen and Liposomal Peptide that is easily absorbed by skin and improve skin elasticity. Brightens and hydrates skin with rice ferment filtrate and hyaluronic acids. Creamy serum-like lightweight texture that leaves no sticky feeling behind. How To Use Apply an appropriate amount on skin around eyes at the last step of skincare routine.', 121.78, 116.0, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7rdvg-mdclu7syt5nq22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F27439759079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598726328', 'Marreta Oitavada, Cabo De Madeira, 3000g, 1pc // Sparta', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL MARRETA OITAVADA 3000G, CABO DE MADEIRA, 1 PC//SPA A Marreta 3kg Profissional Aço Fundido Cabo Longo Madeira SPARTA é a ferramenta perfeita para quem busca eficiência e durabilidade. Com um peso de 3000g, esta marreta é ideal para trabalhos pesados, proporcionando a força necessária para qualquer tarefa. O cabo longo de madeira oferece um manuseio confortável e seguro, permitindo um melhor controle durante o uso. Além disso, o material de madeira absorve o impacto, reduzindo a tensão nas mãos e nos braços durante o trabalho prolongado. A cabeça de aço forjado garante a resistência e a durabilidade que você precisa. Este modelo de marreta oitavada é reconhecido pela sua robustez e capacidade de resistir a condições de trabalho intensas. A Marreta 3kg Profissional Aço Fundido Cabo Longo Madeira SPARTA é uma ferramenta indispensável para profissionais que buscam qualidade e desempenho em seu trabalho. Adquira a sua e experimente a diferença de uma ferramenta de alto padrão. - PERGUNTAS FREQUENTES - 1. O produto acompanha Nota Fiscal? R: Todos os produtos vendidos pela COMASP FERRAMENTAS acompanham Nota Fiscal. Verifique seu cadastro e endereço de entrega, antes de efetuar a compra. 2. Emitimos nota fiscal para CNPJ? R: Emitimos nota fiscal para Contribuinte e Não Contribuinte. 3. Os produtos são Novos e possuem Garantia? R: Todos os produtos são novos e possuem garantia por parte do Fabricante.', 130.0, 130.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-mc7ur0p63gxd07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F22598726328', NULL, NULL, '2026-