INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14566886522', 'Alarme Automotivo PST Positron Cyber PX360BT Bluetooth', 'Alarme Automotivo PST Positron Cyber PX360BT Bluetooth Com a função modo assalto passivo por interruptor de porta ou ignição,quando a ignição for ligada ou uma porta do veículo for aberta, o alarmedispara e bloqueia, de maneira progressiva, o motor de partida. O aplicativo Pósitron alarme permite que você tenha todas as funções docontrole remoto na tela do seu smartphone: ativar e desativar o alarmePX360BT, desativar o sensor de ultrassom, acionar o pisca setas, luz deaproximação e saídas auxiliares e muito mais. MODELO DO PRODUTO CYBER PX360BT BLUETOOTH ALIMENTAÇÃO 12VOLTS INTEGRAÇÃO SMARTPHONE Integração via Pósitron App - Aplicativo para comandos do alarme via Celular APLICAÇÃO Universal - Carros CONTROLE REMOTO 01 unid PXN74 (convencional) 01 unid DPN74 (de presença) CONEXÕES AUXILIARES 02 Saídas Auxiliares CONTEÚDO DA EMBALAGEM 02 controles remotos 01 Módulo Central 01 Sirene 02 Sensores internos 01 Chicote de Instalação 01 Manual de Instruções GARANTIA 3 ANOS BLUETOOTH "Aplicativo Pósitron Alarme(Comandos do Alarme via Celular)"', 445.0, 409.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/21f09c0573cf701249192a2b4fcda7cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F14566886522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53652660597', 'Assento Sabatini Soft Close Polipropileno AST900 Branco – Conforto, Qualidade e Encaixe Perfeito', 'O Assento Sanitário Sabatini Soft Close Polipropileno AST900 Branco, AST809 Verde Claro e AST803 Cinza é a solução ideal para quem busca conforto, resistência e alta durabilidade no banheiro. Compatível com a bacia Sabatini Icasa, possui sistema Soft Close, que evita batidas bruscas, prolonga a vida útil do produto e aumenta a segurança no uso diário. Fabricado em polipropileno de alta qualidade, entrega superfície brilhante, higiênica e fácil de limpar. Equipada com tampa envolvente, o assento oferece melhor acabamento visual e maior proteção. Conta com fixador ajustável e fixador antiderrapante, garantindo encaixe firme, estabilidade e instalação simples. Medidas aproximadas de compatibilidade (bacia Sabatini Icasa): Comprimento: 43–45 cm | Largura: 35–37 cm | Distância entre furos: ajustável de 14 a 18 cm. Características: Modelo: AST900 Branco Modelo: AST809 Verde Claro Modelo: AST803 Cinza Material: Polipropileno Sistema: Soft-Close Tampa envolvente Superfície brilhante Higiênico e resistente Ideal para residências, apartamentos, banheiros comerciais e lavabos que exigem praticidade e acabamento moderno. Para maior durabilidade, limpe com água e sabão neutro e use pano macio.', 499.9, 199.9, NULL, 'Home & Living > Bathrooms > Toilet Bowls, Seats & Covers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhwcgktm4phe7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384728500%2F53652660597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57002126681', 'TIRTIR Make Up Fixer Collection', '💗 1. Máscara de Máscara de Configuração Impermeável Fit Spray de Configuração Impermeável (Rosa) ✔ Características da chave Fórmula à prova d''água forte, à prova de suor e à prova de manchas Evita que a maquiagem derrete ou se mude Ideal para atividades ao ar livre ou longos dias Deixa um acabamento fosco macio com brilho sutil 🍑 2. Máscara Fit Fixador Maquiagem Pêssego Edição ✔ Características da chave Fragrância de pêssego doce e doce Fechaduras na maquiagem mantendo a pele hidratada Acabamento leve, não pegajoso e refrescante Ótimo para looks de maquiagem natural diariamente, ótimo para diariamente 🧡 3. Máscara Encaixe Fixador Maquiagem Todos os Dias (Laranja) ✔ Características da chave Desempenho máximo de longo desgaste de longa duração Reduz significativamente a transferência nas máscaras Textura não pegajosa e de secagem rápida Melhor para os dias de trabalho, eventos ou desgaste diário 💙 4. Máscara Fit Maquiagem Fixo Cool (Azul) ✔ Características da chave Efeito calmante e de resfriamento instantâneo instantâneo e calmante Ajuda a acalmar o calor da pele e controlar o brilho da pele Perfeito para ambientes ao ar livre perfeitos para verão, treinos ou ambientes ao ar livre Acabamento leve, fresco, semi-fosco ❤️ 5. Fixador Maquiagem Mask Fit (Vermelho) – Versão Original ✔ Características da chave O spray de fixação padrão clássico e bem equilibrado Melhora a aderência e prolonga o tempo de desgaste Adequado para todos os tipos de pele Acabamento semi-fosco Natural Natural Natural 📌 Modo de usar (mesmo para todos os Sprays) ✔ Depois de concluir a maquiagem Agite bem o frasco. Agite bem o frasco. Segure-o a 30 cm de distância do seu rosto. Segure-o a 20–30 cm de distância do rosto. Pulverize uniformemente em forma de Z ou pulverize uniformemente em movimentos circulares ou em forma de Z. Deixe secar completamente sem tocar no rosto. ✔ Dica PRO Para aderência extra, borrife levemente em uma esponja e pressione-a na pele durante a maquiagem base. Spray de pulverização de 2 a 3 camadas para um efeito duradouro mais forte de 2 a 3 camadas.', 99.45, 99.45, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134207-8227h-mhirc0ijzw1x4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F57002126681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23084046890', 'Dr.Jart+ Ceramidin ™ Skin Braining Hidration Mask *5ea, 22g', 'Ceramida™ Máscara Hidratante para Barreira de Pele 22g*5ea Descrição do produto Quando sua barreira de pele precisa de algo extra, esta máscara de folha é sua amiga. Revestida em nossa Solução Fortalecedora Barreira carregada com Ceramida NP mais Pantenol e Glicerina, transborda a pele com umidade e fortalece a barreira da pele. Revestido com mais 2x NP de Ceramida, além de Pantenol e Glicerina, esta máscara nutritiva de folha nutritiva abraça a pele e deixa-a macia e flexível. Também ajuda a reduzir a aparência de linhas finas e secas. O Pantenol para hidratar, reforçar a barreira da pele e ajudar a prevenir a futura perda de água.', 131.49, 125.0, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134207-7rbm1-ln2xyzchmeffb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F23084046890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
