INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497909608', 'Maleta de Ferramentas Benoá TOL-37 Kit 108 Peças Alicate / Martelo', 'Maleta de Ferramentas Benoá TOL-37 Kit 108 Peças Alicate / Martelo Maleta de Ferramentas Benoá é o seu companheiro confiável para todas as tarefas de manutenção e reparos. Com um conjunto abrangente de 108 peças, incluindo alicate e martelo de alta qualidade, esta maleta foi projetada para oferecer desempenho excepcional e durabilidade, tornando-a uma escolha indispensável para o seu arsenal de ferramentas. Kit conta com 108 peças meticulosamente selecionadas, este kit oferece variedade impressionante de ferramentas para enfrentar uma ampla gama projetos. Desde reparos simples até tarefas mais complexas, você terá a ferramenta certa ao seu alcance. Quantidade de peças: 108 Peso (kg): 4.2 Dimensões (AxLxP): 8,2 x 41,5 x 29 cm Referência: TOL-37 Itens Inclusos: - 1 maleta com 108 peças Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Este produto não inclui montagem e instalação. Não nos responsabilizamos, no ato da entrega, por desmontagens, subir escadas, elevadores ou transporte por guincho para apartamentos. Eventuais despesas são de responsabilidade do cliente. Garantia Fabricante: 3 meses', 408.9, 408.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-m15mp5e2jyz27c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F23497909608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
