INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57409930337', 'Ração Quatree Light Adulto Castrado Raça Pequena 2,5kg', 'Quatree Supreme Adultos Light/Castrados Raças Pequenas Frango e Salmão com Brócolis e Batata-Doce – 2,5kg Descrição Alimento completo Super Premium indicado para cães adultos de raças pequenas, especialmente castrados ou com tendência ao sobrepeso. Sua fórmula possui teor reduzido de gorduras, fibras especiais e carboidratos complexos, auxiliando no controle do apetite e manutenção do peso. Produzido com ingredientes naturais, sem transgênicos e sem antioxidantes artificiais (BHT e BHA). Benefícios - Controle de peso e apetite: com L-carnitina e teor reduzido de gorduras, auxiliando na queima de gordura corporal - Maior saciedade: fibras e carboidratos complexos ajudam o cão a se sentir satisfeito por mais tempo - Saúde intestinal: contém prebióticos (FOS, MOS e beta-glucanas) e probióticos - Pele e pelagem saudáveis: presença de ômegas 3 e 6, além de EPA e DHA - Saúde oral: com hexametafosfato de sódio, que auxilia na redução do tártaro - Articulações protegidas: enriquecido com glicosamina e condroitina - Redução do odor das fezes: contém extrato de yucca - Antioxidantes naturais: alecrim, chá verde e tocoferóis Indicação Indicado para cães adultos castrados ou com tendência ao ganho de peso, de raças pequenas. Embalagem disponível 2,5kg Informações Nutricionais (resumo) - Proteína bruta: 30% - Gorduras: 8% - Fibras: 4,5% - L-carnitina: 250 mg/kg - Ômega 3: 0,20% - Ômega 6: 2,10% - Energia metabolizável: 3.545 kcal/kg', 105.16, 105.16, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-820lt-mnu56wzu7caq99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F57409930337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
