INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8662267334', 'Alicate Amperímetro Fluke 302+ com Bolsa 400a - 600v', 'Alicate Amperímetro Fluke 302+ Digital CAT III 600V True RMS Descrição do Produto O Alicate Amperímetro Fluke 302+ é ideal para profissionais que buscam precisão, segurança e praticidade em medições elétricas. Compacto, ergonômico e resistente, ele oferece medições confiáveis para manutenção elétrica residencial, comercial e industrial. Seu design moderno proporciona conforto durante o uso, enquanto a garra de 30 mm facilita medições em diferentes aplicações. Conta ainda com visor LCD iluminado para melhor visualização em ambientes com pouca luz. Principais Características: - Mede corrente AC até 400ª; - Display LCD com iluminação de fundo; - Design compacto e ergonômico; - Garra de 30 mm; - Medição de tensão AC/DC; - Teste de resistência e continuidade; - Alta segurança: CAT III 600V / CAT IV 300V; - Fácil de transportar e utilizar; - Ideal para eletricistas e técnicos. Especificações Técnicas: Corrente Alternada (AC): - Faixa: 400ª; - Precisão: ±(1,8% + 5 dígitos). Tensão Alternada (AC): - Faixa: 400V / 600V; - Precisão: ±(1,5% + 5 dígitos). Tensão Contínua (DC): - Faixa: 400V / 600V; - Precisão: ±(1,5% + 5 dígitos). Resistência: - Faixa: 4k; - Precisão: ±(1% + 5 dígitos). Informações Gerais: - Continuidade sonora: 70; - Taxa de atualização: 2 vezes por segundo; - Temperatura de operação: 0°C a 40°C; - Alimentação: 2 pilhas AAA; - Dimensões: 208 x 58,5 x 28 mm; - Abertura da garra: 30 mm; - Categoria de segurança: CAT III 600V / CAT IV 300V. Itens Inclusos: - 1 Alicate Amperímetro Fluke 302+; - 2 Pilhas AAA; - Pontas de prova TL75; - Bolsa para transporte; - Manual do usuário.', 629.0, 427.72, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lq-mnx6a4