INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498005271', 'kit4 Smart Luminária Inteligente Ultra LED com sensor de movimento sem fio e Recarregável USB fino barra 10/20/30/50cm', '💡 Luminária LED Barra com Sensor de Movimento Recarregável 💡 Prática e eficiente, esta luminária acende automaticamente ao detectar movimento, trazendo iluminação e segurança aos ambientes de forma econômica e fácil. Ideal para locais como armários, corredores, escadas e guarda-roupas, ela oferece conforto e praticidade com sua instalação por fita magnética — sem necessidade de parafusos! Características Principais: • Iluminação Automática: Sensor de presença sensível, detecta até 2,5 metros com um ângulo de 120° • Fácil Instalação: Fita magnética adesiva inclusa, sem necessidade de ferramentas • Opções de Cor de Luz: Branco Frio ou Branco Quente • Material: Plástico resistente com componentes eletrônicos de alta qualidade • Fonte de Energia: Recarregável via USB • Bivolt: 110/220V • Tamanhos Disponíveis: 10cm, 20cm, 30cm, 50cm • Potência: 5W • Dimensões Aproximadas: 20,5 cm (C) x 2,5 cm (L) • Peso: 60g Itens Inclusos: 01x Luminária LED com Sensor de Movimento 01x Cabo Micro USB 02x Fitas Adesivas Magnéticas para Fixação 🔋 Iluminação inteligente para todos os ambientes!', 128.0, 47.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7reqg-m22le89lz69ha9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F23498005271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251675669', 'Pendentes iluminação Simples Retro Colorido 1M Modelo Moderno E27 110V-220V Bivolt', 'Pendente Iluminação Simples Retrô Colorido Moderno E27 | 1 Metro | Bivolt Visual marcante, preço amigo e aquele charme clássico que nunca sai de cena. Esses pendentes são a escolha certeira para quem quer dar personalidade ao ambiente sem complicar a instalação. Destaques do Produto Bivolt (110V–220V) — plugou, funcionou. Soquete E27 — compatível com a lâmpada mais comum do mercado. Cabo de 1 metro — tamanho ideal para compor mesas, bancadas, corredores e cantos decorativos. Estilos para todos os gostos: Pendentes Coloridos: Cinza, Verde, Azul, Rosa, Branco Pendentes Retrô: Cobre, Preto, Dourado, Prata, Rosa Pendentes Simples: Verde, Rosa, Branco, Salmão Por que escolher? São leves, modernos, versáteis e carregam um toque nostálgico que cai bem em qualquer decoração — da moderna à clássica.', 36.0, 19.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi1jngwfsk5i69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F58251675669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
