INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394173979', 'Tamanco Piccadilly Conforto Detalhes Feminino - Preto', 'OTamanco Piccadilly Conforto Detalhes Femininocombina conforto e charme é uma ótima escolha pra quem busca passeios casuais. A palmilha é exclusiva, super macia e de fácil limpeza. O solado gel é supermacio, flexível e aderente. Um mix de conforto, beleza e praticidade em um único produto. Garanta já o seu!', 199.9, 179.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7ra2t-mbdv6rx86j1lbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F23394173979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
