INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599831595', 'Cômoda Penteadeira 8 Gavetas com Espelho Porto', 'A Cômoda 8 Gavetas Porto da Politorno Móveis é a escolha perfeita para quem precisa de ainda mais espaço sem abrir mão do design elegante e contemporâneo. Com visual clean e acabamento em pintura UV branco e freijó semi fosco, essa peça da Linha Porto traz sofisticação e praticidade ao ambiente, sendo ideal para quartos que exigem organização com estilo. Com 209 cm de largura, 160 cm de altura e 46 cm de profundidade, ela oferece excelente capacidade de armazenamento por meio de 8 gavetas espaçosas, ideais para acomodar roupas, acessórios, documentos e outros itens do dia a dia com total funcionalidade. Fabricada em MDP de alta qualidade, é resistente, durável e de fácil limpeza, tornando-se uma solução completa para manter seu espaço sempre organizado, bonito e harmonioso. Estilo: Moderno Peso (kg): 62 Garantia: 06 Meses Altura (cm): 160 Acabamento: Pintura UV Largura (cm): 209 Possui Pés: Não Possui Nichos: Não Possui Portas: Não Fita Integrada: Sim Possui Gavetas: Sim Suporta Até (kg): 30 Tipo de Cômoda: Adulto Possui Espelhos: Sim Profundidade (cm): 46 Escala de Brilho: Semi-Fosco Gaveta com Chave: Não Serviço Montagem: 114259443 Altura do Espelho: 71 Material do Fundo: MDP Origem do Produto: Nacional Ambiente Principal: Quarto Formato do Espelho: Retangular Largura do Espelho: 53 Material da Gaveta: MDF/MDP Material Principal: MDF/MDP Possui Prateleiras: Não Sapatas Niveladoras: Não Acabamento da Gaveta: Pintura UV Espessura do Espelho: 3 Peso Máximo por Gaveta: 5 Quantidade de Espelhos: 1 Tipo de Puxador da Gaveta: Embutido Escala de Brilho da Gaveta: Semi-Fosco Tipo de Fixação do Espelho: Fita Dupla Face Tipo de Corrediça da Gaveta: Metálica Telescópica Marca: Politorno Cor Interna: Freijó Cor: Branco/Fre