INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597483687', 'Colchão Casal D65 Viena 138x188x25 Casal', 'Este colchão de espuma foi desenvolvido para agregar conforto, já que é formada por espumas de alta densidade, que garantem alta durabilidade ao produto. Internamente o colchão conta com o novo sistema de conforto Ergoplus . Sua estrutura interna foi desenvolvida para garantir que o seu corpo permaneça em uma posição uniforme ao dormir, refletindo em ótimos benefícios para sua noite de sono. Além do mais, conta com uma camada de espuma localizada na parte superior do colchão, proporcionando um excelente conforto ao usuário. Por sua concepção não há necessidade de virar o colchão, apenas gira-lo periodicamente para garantir que a espuma se acomode de forma mais uniforme. Peso (kg): 33 Garantia: 06 Meses Altura (cm): 25 Antiácaro: Sim Antifungo: Sim Largura (cm): 138 Ortopédico: Não Antialérgico: Sim Precisa Virar: Não Comprimento (cm): 188 Suporta Até (kg): 150 Tipo de Espuma: Espuma Poliuretano Tipo do Colchão: Espuma Nível de Conforto: Firme Origem do Produto: Nacional Ambiente Principal: Quarto Possui Certificado: Sim Densidade da Espuma: D-65 Revestimento do Colchão: Malha Serviço Impermeabilização: 102610509 Marca: Herval Cor do Produto: Bege Itens Inclusos: 1 Colchão de espuma Cor Predominante: Bege Linha ou Coleção: Viena Tipo de Certificado: INMETRO', 1661.63, 1661.63, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-824ig-mffh4tr14ky082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22597483687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
