INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252194616', 'Macarrão Instantâneo Lámen Tomate Suave Turma da Mônica Nissin', 'O macarrão instantâneo Lámen Nissin sabor Tomate Suave da Turma da Mônica é prático, fica pronto em apenas 3 minutos e garante a diversão das crianças! * Modo de Preparo: Fogão: 1. Ferva 450ml de água. 2. Junte o macarrão e cozinhe por cerca de 3 minutos. 3. Retire do fogo, coloque o tempero do envelope e misture bem! Micro-ondas: 1. Coloque 450ml de água e o macarrão em um recipiente próprio para micro-ondas. 2. Cozinhe em potência alta por 5 minutos, parando na metade do tempo para mexer. 3. Retire do micro-ondas, misture o tempero e sirva! A Nissin Foods do Brasil é líder no segmento de macarrão instantâneo e investe sempre em boas práticas para satisfazer as necessidades de seus consumidores.', 3.49, 3.49, NULL, 'Food & Beverages > Convenience / Ready-to-eat > Instant Noodles', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnellw0i68eb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F58252194616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
