INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497566363', 'Boneca Masha Naninha de Pano Masha e o Urso Cotiplás - 2762', 'A boneca Masha Naninha de Pano é uma versão aconchegante e reconfortante da adorável personagem Masha, do desenho animado "Masha e o Urso". Ela é feita com tecidos macios e delicados, projetada para ser uma companheira tranquilizadora para bebês e crianças pequenas durante a hora de dormir. Esta interpretação da Masha é caracterizada por sua expressão amigável e gentil, convidando abraços e carinho. Geralmente feita com materiais seguros e duráveis, como pano e enchimento macio, a Masha Naninha de Pano é uma opção encantadora para crianças pequenas que procuram conforto e segurança na hora de dormir. ESPECÍFICAÇÕES: Material: Vinil cabeça e mãos/Pano corpo Idade recomendada: acima de 3 anos Altura (aproximada): 29 cm Características: - Marca: Cotiplas - Modelo: 2762 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01 Boneca Masha boneca masha e o urso - bonequinha - bonequinha masha e o urso - bonecas - boneca masha - bonequinha de pano - boneca de pano - boneca de pano masha e o urso', 68.0, 68.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd68-lwfval7vtsi463', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F22497566363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
