INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597993054', 'Sandália Feminina Falcucci Papete Gladiadora Flatform Tacha Piramide Confortável Branca Amalf', 'A Sandália Feminina Falcucci Amalf é uma combinação moderna de estilo e conforto. Com um design robusto, inspirado nas clássicas sandálias gladiadoras, ela apresenta tiras largas e ajustáveis que envolvem o tornozelo, garantindo um ajuste seguro e personalizado. Detalhes de tachas em formato de redondo adicionam um toque ousado e contemporâneo ao modelo, enquanto a sola macia oferece um conforto prolongado para o uso diário. A sandália tem uma sola estilo flatform, que proporciona leve elevação, sem abrir mão da estabilidade, tornando-a ideal para quem busca altura com conforto. Fabricada com materiais de alta qualidade e acabamento primoroso, ela é versátil o suficiente para compor desde looks casuais até combinações mais estilosas. Tabela de medidas da palmilha: Nº 33-34 : 23 cm Nº 35-36 : 24 cm Nº 37-38 : 25,5 cm Nº 39-40 : 26,5 cm', 99.99, 49.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1zv4tpeg05t5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324642050%2F23597993054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
