INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798035075', 'Calça Legging Lupo AF Up Control Feminina - Laranja', 'Calça Legging AF Up Control da Lupo possui modelagem desenvolvida especialmente para a prática de atividades esportivas. Com ela, você garante total conforto. Esse modelo é o queridinho das mulheres que buscam um visual mais elegante, é a escolha perfeita para quem busca conforto e praticidade no dia a dia. Design moderno e versátil é perfeito para acompanhar as demandas diárias de toda mulher. Sua versatilidade permite que você o combine com uma variedade de looks. Possui silicone na cintura, que não deixa a calça sair do lugar, compressão na parte posterior das coxas dando o efeito ''''empina bumbum'''' que valoriza as curvas. Possui tecnologia Seamless Dry, sem costura, que diminui os pontos de fricção. - Conta ainda com ventilação estratégica, colocada em zonas críticas de suor, que garante alto conforto térmico. O acabamento Sanitized inibe a proliferação de microrganismos. Garanta já a sua!', 199.9, 179.9, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-m631bdi3b9ts6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F18798035075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
