INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21014466996', 'Painel Redondo Decorativo Geométrico em tecido 1,50m com Elástico para Festas', '>>> PAINEL REDONDO EM TECIDO COM ACABAMENTO EM ELÁSTICO <<< UTILIZAÇÃO EM ESTRUTURAS CIRCULARES ENTRE 1,20 ATÉ 1,50 DE DIÂMETRO. >>> PAINEL NÃO POSSUI EMENDA!!! Com impressão de alta qualidade, cores vivas, imagens nítidas e acabamento perfeito, o painel redondo da Ideal é o detalhe perfeito para ter resultado incrível em sua decoração, com ótimo custo x benefício. DETALHES DO PAINEL EM TECIDO: >>> Tecido Malha New (Que estica e não amassa). >>> Tecido Leve com ótimo caimento >>> Gramatura: 140g/m de excelente qualidade. >>> Composição do Tecido: 95% Poliéster e 5% de Elastano. >>> Elástico costurado ao redor do painel. >>> Acabamento em overloque evitando que o painel desfie. PORQUE ESCOLHER O PAINEL SUBLIMADO DA IDEAL: >>> Melhor opção para quem procura ótimo custo x benefício >>> Não amassa (por ser feito em tecido especial. Bem melhor do que os de lona) >>> Não desbota, por ser sublimado em tecido >>> Pode ser lavado quantas vezes desejar >>> Seca rapidamente depois de molhado >>> Pode ser passado (recomendamos não usar alta temperatura) >>> Instale na estrutura circular em alguns minutos >>> Sua decoração muito mais cheia de vida >>> Alta durabilidade >>> Não reflete luz na hora das suas fotos PRAZO DE PRODUÇÃO E ENVIO: - TODOS OS PEDIDOS ACOMPANHAM NOTA FISCAL. - Os nossos painéis são produzidos e postados em até 1 DIA ÚTIL após pagamento aprovado. - Nosso painel possui garantia contra defeito de fabricação.', 89.9, 54.9, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lje4pwh7bvp18b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F21014466996', NULL, NULL, '2026-07-28T0