INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899357040', 'Pingente de Prata 925 Mão de Fátima Vazada', 'Pingente de Prata 925 Mão de Fátima Vazada O Pingente de Prata 925 Mão de Fátima Vazada é um símbolo de proteção e sorte, com um design delicado e elegante. Este acessório é perfeito para quem deseja carregar consigo um amuleto poderoso e cheio de significado. Especificações: Tamanho: 2cm (20mm) Peso: 0.97g Material: Prata 925 Características Principais: ✔ Design Vazado: O detalhe vazado proporciona leveza ao pingente, destacando a beleza do símbolo da Mão de Fátima. ✔ Prata 925: Feito com prata de alta qualidade, o pingente garante durabilidade e um brilho duradouro. ✔ Amuleto de Proteção: A Mão de Fátima é conhecida por afastar energias negativas e trazer sorte. ✔ Versatilidade: Pode ser usado com diversos tipos de correntes, combinando com diferentes estilos e ocasiões. Descrição Detalhada: O Pingente de Prata 925 Mão de Fátima Vazada é mais do que um simples acessório; é um símbolo de proteção e boas energias. Com seu design vazado, este pingente é uma peça delicada e ao mesmo tempo impactante, ideal para quem busca um toque de espiritualidade no seu dia a dia. Cuidados com o Pingente: Para preservar o brilho do seu Pingente de Prata 925, evite o contato com produtos químicos e guarde-o em um local seco e protegido. Limpe regularmente com uma flanela macia para manter sua aparência original. Adquira o Seu: Leve para casa um símbolo de proteção e beleza com o Pingente de Prata 925 Mão de Fátima Vazada. Um acessório essencial para quem deseja se conectar com boas energias.', 94.0, 57.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m33qdu9w48at83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F