INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14342978840', 'Espumante Salton Demi Sec 750ml', 'A empresa foi formalmente constituída em 1910 quando os irmãos Paulo, Angelo, João, Cesar, Luis e Antonio deram cunho empresarial aos negócios do pai, o imigrante Antonio Domenico Salton. Salton é reconhecida como uma das principais vinícolas do País. Na extensa lista de conquistas destes mais de 100 anos de história comemora o fato de ser familiar e 100% brasileira. Com a terceira geração à frente da empresa, tanto na Unidade em Bento Gonçalves quanto em São Paulo, revela em seus quadros a quarta geração Salton, que promete o mesmo empenho e dedicação com que a empresa foi comandada até agora.', 44.9, 44.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/c26fde7d39bcd3402b233935eeddecc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F14342978840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398105115', 'Lápis Eternal Infinito Lápis Decorado Glitter Papelaria Fofa Lápis de Escrever Material Escola', 'Os lápis infinitos são incríveis porque podem substituir até 100 lápis tradicionais usando pontas comprimidas. Essas pontas não precisam ser apontadas e duram o suficiente para economizar. Feito de material plástico de alta qualidade, é durável e ecológico. Pode ser usada em casa, escola, escritórios, pode escrever até 500,000 palavras continuamente. Com borracha na sua parte interior, para apagar seus erros As cores são enviadas de forma sortida, sendo assim, NÃO é possível escolher cor. Temos várias opções <3', 29.9, 17.01, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3yxyfg8lhytf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F22398105115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998092852', 'Cortina Infantil - 2,00 x 1,50 Menino Menina Baby - Decorativa - Fada Game Princesa Futebol Bombeiro', 'Uma cortina infantil é um item decorativo e funcional que é especialmente projetado para quartos de crianças. Além de embelezar o ambiente, a cortina infantil tem a função de bloquear a luz excessiva, ajudando a criar um ambiente mais confortável para o sono das crianças. Esses itens são ideais para criar um ambiente acolhedor, colorido e estimulante, combinando com o restante da decoração do quarto infantil. CONTÉM: Cortina 2,00 largura x 1,50 altura COMPOSIÇÃO: 100% Poliéster Cortina decorativa - NÃO SÃO CORTINAS BLACKOUT -NÃO USAR ALVEJANTE -NÃO DEVE SER PASSADO -SECAR NA SOMBRA. OBS: Não acompanha varão', 120.0, 71.99, NULL, 'Home & Living > Decoration > Curtains & Blinds', 'https://cf.shopee.com.br/file/sg-11134201-7rd70-m7rx254k02y956', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443294432%2F20998092852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48250809086', 'Garrafa Térmica Aço Inoxidável 1700ml Isolada a Vácuo Grande Capacidade Com Canudo', 'Marca: MODUS Design exclusivo: Com o botão One Touch Open and Close e a tampa higiênica flip top. A tampa e o canudo podem ser desmontados de forma independente e são fáceis de limpar. Material de alta qualidade: Feito de aço inoxidável e Sem BPA , a garrafa de água isolada a vácuo de metal significa melhor retenção de calor e frio e impede a condensação do lado de fora. À prova de vazamentos e fácil de beber: A tampa com trava à prova de vazamentos evita 100% de vazamentos. Além disso, a garrafa de água tem um canudo longo que chega até o fundo, para que você possa beber facilmente. Grande capacidade de 1700ML : a garrafa de água tem a capacidade de atender às suas necessidades diárias. Seja em uma caminhada ou em um acampamento, você pode aproveitá-la com confiança. Presente perfeito: esta garrafa de água é o melhor presente para sua família, mãe, pai, marido, esposa, amantes, vizinhos, amigos, colega de trabalho.', 259.98, 99.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m26fdqtp9mfqff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F534109767%2F48250809086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892252697', 'Desodorante Aerossol Old Spice Refrescante 93g', 'O Desodorante Aerossol Antitranspirante Old Spice Pegador proporciona proteção duradoura além de deixar a sua pele com perfume prolongado. Mantém as axilas cheirosas e frescas, sem irritar a pele. Modo de uso: Aplique nas axilas a pelo menos 15cm de distância.', 26.61, 26.61, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6gtmxbvcimff0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23892252697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499189715', 'Corretivo Líquido Dailus Bye Bye Olheira D10 Escuro', '#html-body [data-pb-style=BJ896D7]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Corretivo Líquido Bye Bye Olheira da DAILUS chegou com tudo! Com média a alta cobertura e acabamento acetinado, é ideal pra disfarçar olheiras, corrigir imperfeições e uniformizar o tom da pele. Com longa duração e resistência à água, sua fórmula é enriquecida com o poderoso bioativo Berryflux Vita, que promove hidratação profunda, estimula a produção de colágeno e suaviza linhas finas e rugas. E ele também não acumula nessas regiões, viu? Com textura confortável, permite ainda a construção de camadas e não craquela! Tudo isso com a ajuda de seu aplicador incrível em formato espátula, que facilita a aplicação. A novidade ainda é vegana, hipoalergênica, livre de parabenos, cruelty-free, dermatológica e oftalmologicamente testada. Demais! A sua paleta democrática acompanha as cartelas da Base Ultra Cobertura Matte e do Pó Compacto Ultrafino. Assim, você pode ter o seu kit completo, sem medo de errar na cor! Sobre o tom: O D.10 é um marrom canela, com fundo neutro amarelado. Indicado para peles retintas que sempre bronzeiam e são mais resistentes a queimaduras de sol. Se você quer ter uma ideia da cor, pense num chocolate quente com canela! E antes de chegar até você, essa belezinha passou por uma série de avaliações no Instituto de Pesquisa Clínica, viu? Confira só os principais resultados depois de 30 dias de uso: -91% dos participantes concordam que o corretivo tem média a alta cobertura -88% concordam que o produto disfarça sinais de cansaço e neutraliza imperfeições e olheiras -88% sentem que a pele permanece hidrata durante o uso -85% concordam que o produto não acumula e não pesa na pele -76% afirmam que o produto auxiliou na redução de linhas finas e de expressão Por que amamos? -Corrige imperfeições e uniformiza a pele -Hidratação profunda com bioativo de skincare: Berryflux Vita -Estimula a produção de colágeno -Suaviza linhas finas e rugas -Média a alta cobertura -Acabamento acetinado -Textura confortável -Não acumula e não craquela -Resistente à água -Longa duração -Hipoalergênico -Dermatológica e oftalmologicamente testado -Livre de parabenos -Vegano e cruelty-free MODO DE USO Gosta de alta cobertura? A nossa dica é aplicar produto na região das olheiras e no canto externo dos olhos. Espere alguns segundos e, em seguida, com um pincel de cerdas curtas e firmes, dê batidinhas pra esfumar o corretivo. Se você sentir a necessidade, repita o processo pra construir camadas.', 66.64, 66.64, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-7rccr-lr3iyiq44iq0d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19499189715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598023200', 'Jogo 2 Pneus Firestone Aro 15 Destination M/T 23 31X10.5R15 109Q LT', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Firestone A marca Firestone foi fundada em Ohio nos Estados Unidos, 1900. Há mais de um século os pneus Firestone equipam veículos com alta qualidade e segurança. A confiabilidade de utilizar um pneu bom, seguro e acessível, faz dos pneus Firestone uma ótima opção para o seu veículo, seja para lazer ou trabalho. Com diversas linhas disponíveis, sem dúvida uma delas vai atender à sua necessidade, com a garantia da experiência de uma marca tradicional no mercado de pneus e a garantia de utilizar o que há de melhor no desenvolvimento de pneus.', 2645.74, 2417.33, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rbka-m5vjc5onkuvi9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F19598023200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293016467', 'Jogo 2 Pneus Itaro Aro 16 IT101 265/70R16 112T', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. A segurança e conforto que você procura para o seu SUV está no Itaro IT101! O desenho da banda de rodagem é simétrico, com sulcos mais largos para dissipar a água com maior velocidade, diminuindo as chances de aquaplanagem. Com baixa resistência ao rolamento, o IT101 oferece melhores condições para a economia de combustível e excelente dirigibilidade. O desenho do ombro foi otimizado para melhorar o apoio no solo, aumentar a aderência e proporcionar maior conforto com menos ruído. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias. Garantia Especial Itaro A Garantia Especial Itaro foi pensada para que você possa rodar com segurança e tranquilidade, com os pneus nascidos para contar histórias. São 180 dias contra Danos Acidentais, que impossibilitem o pneu de ser reparado. Ou seja, em casos de pequenas avarias, em que há conserto constatado por um profissional indicado pela PneuStore, a troca não é aplicada. Consulte o regulamento completo acessando a nossa página de garantias: Garantia Especial Itaro.', 1325.22, 1266.69, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd4p-lvemkf92nxzc47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22293016467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204089053', 'Barra De Proteína 50g Sabor Amendoim Caixa 8 Un - Everlast', 'Barra de Proteína Everlast Sabor Amendoim com Recheio de Caramelo 8 Unidades A Barra de Proteína Everlast sabor amendoim com recheio de caramelo combina praticidade, nutrição e sabor em um snack funcional para o dia a dia. Com textura agradável e 15g de proteína por unidade, é uma opção conveniente para complementar a alimentação em diferentes momentos. Produzida com whey protein concentrado e isolado, não possui adição de açúcares e é livre de glúten, oferecendo equilíbrio entre nutrição e sabor. Sua composição também conta com fibras alimentares, contribuindo para uma rotina alimentar equilibrada. Ideal para: Pessoas que buscam complementar a rotina com mais energia e desempenho no dia a dia, incluindo praticantes de atividades físicas e indivíduos com uma rotina ativa. Benefícios • 15g de proteína por unidade • Contribui para o aporte diário de proteínas • Auxilia na manutenção da massa muscular • Promove maior saciedade entre as refeições • Praticidade para consumo em qualquer momento do dia • Sem adição de açúcares • Zero glúten • Fonte de fibras alimentares Sabor: amendoim com recheio de caramelo Recomendação de uso Consumir 1 unidade ao dia ou conforme orientação de profissional. Alérgicos: contém derivados de leite e soja. Contém lactose.', 89.9, 72.14, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-820ls-mlytgzaqfjt347', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F706221503%2F58204089053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
