INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094417432', 'Phytoterápica Body Splash Aquarelle Orvalho 200ml – Vegano, Refrescante, Leve e Natural para o Dia', 'A leveza da natureza em cada borrifada. O Body Splash Aquarelle Orvalho da Phytoterápica traz uma fragrância verde, fresca e revigorante, ideal para quem busca um toque sutil e natural no dia a dia. Com formulação vegana e ingredientes seguros para a pele, ele oferece bem-estar sem agredir o corpo nem o meio ambiente. Benefícios: Perfume suave com notas verdes e frescas. Prolonga a sensação do banho recém-tomado. Fórmula natural, vegana e livre de parabenos. Ideal para o corpo e também para aromatizar roupas e ambientes. Embalagem prática de 200ml com borrifador. Informações Técnicas: Volume: 200ml. Textura: líquida. Indicação: uso corporal. Livre de ingredientes sintéticos agressivos. Vegano e não testado em animais. Marca: Phytoterápica. Ideal para: Quem prefere fragrâncias mais leves e refrescantes. Uso diário para manter a sensação de frescor. Aromatizar ambientes e roupas de forma natural. Sobre a Phytoterápica: Referência em cosméticos naturais e aromaterapia, a Phytoterápica desenvolve produtos com ingredientes puros, veganos e sustentáveis. Cada fórmula é pensada para promover bem-estar, respeitando seu corpo e o meio ambiente.', 70.0, 70.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820lu-mp15d0g4pa815a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137364730%2F22094417432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
