INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899262516', 'Pneu Itaro Aro 17 IT302 225/50R17 94W Run Flat', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias.', 858.97, 798.85, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd4k-lvm6vhngzo1nc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F21899262516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51955782639', 'Óculos De Solda Para Soldador Com Escurecimento Automático Premium', 'Instruções de compra: 1. Envio dentro de 24 horas após o pedido, com envio de São Paulo. 2. Atendimento ao cliente disponível 24 horas para responder a perguntas. 3. Todos os produtos são 100% conformes e possuem certificados de conformidade. Faça sua compra com confiança. 4. Devoluções gratuitas em caso de problemas de qualidade dos produtos. Informações do produto: Óculos De Solda Para Soldador Sua versatilidade ajuda o soldador a se sentir mais livre para soldas intermitentes, porém o cuidado com a falta de proteção para o rosto comparado com uma máscara de solda faz com que ele não a substitua para todos os casos. Especificações : * Tamanho do filtro: 108 x 50 x 5,5cm * Tamanho de visualização: 90 x 30mm * Tonalidade escura: DIN11 * Temperatura de operação: -10-65ºC * Tempo de comutação: 1 / 10000s * Tempo de atraso: 0.1-0.8s * Fonte De Energia Bateria De Lítio E Carregamento Solar * Materiais: PC e ABS * Tamanho: AXLXC 05x 05 x 14cm * Peso: 111 GRAMAS Embalagem incluída: 1 Óculos De Solda Para Soldador Garantia do vendedor: 30 dias', 59.99, 32.99, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk9zgv2ewao10c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435277938%2F51955782639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398019250', 'Reparo Bico Injetor Fiat Prêmio 1994 a 1996 - 515803 - 1201', 'Reparo Bico Injetor Fiat Prêmio 1994 a 1996 515803 1201 Motor 1.5/1.6 8v - (Sistema Magneti Marelli) (Single Point) (2 Filtros + 2 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 26.82, 26.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7repa-m2f0qdbnfpq04b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23398019250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
