INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23636705912', 'Camisa Alemanha Retrô 1990 Oficial', 'Modelo clássico, a Alemanha de 1990 conquistou o Mundo. O modelo retrô ostenta o orgulho pela seleção. Desenvolvida em algodão leve e confortável utilizando processos de envelhecimento do algodão como as históricas camisas da época, este manto sagrado faz alusão ao histórico título mundial de 1990. Uso casual, indicado para momentos de lazer e ir ao estádio. Características: - Composição: 100% Algodão - Escudo: Bordado - Faixas frontal: Silk - 2 tiras pretas laterais nas mangas. - Número nas costas: N/A_ Medidas Aproximadas: Largura x Altura - P (BR): 50 x 69 - M (BR): 52 x 71 - G (BR): 54 x 73 - GG (BR): 56 x 75 - XG (BR): 62 x 78 Informações Adicionais: - Todos os produtos a pronta entrega. - Envio imediato. - Garantia: Contra defeito de fabricação.', 199.9, 179.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1r5zwdwm7qie3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F23636705912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
