INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54906291019', 'BOBINA DE PULSO MAGNETRON FAN 125 2009 A 2015 / START 160 2016 A 2020', 'BOBINA DE PULSO MAGNETRON – peça essencial do sistema de ignição, responsável por gerar o sinal de referência para o módulo (CDI/ECU), informando rotação e posição do motor. Quando apresenta falhas, pode causar dificuldade na partida, cortes de giro e funcionamento irregular. Compatibilidade (conforme aplicação do fabricante): Fan 125 – 2009 a 2015 Start 160 – 2016 a 2020 Vantagens: Produto novo, de alta durabilidade Sinal estável para melhor desempenho da ignição Ótima reposição para manutenção preventiva ou corretiva Encaixe conforme padrão da aplicação Especificações: Marca: Magnetron Tipo: Bobina de pulso / sensor de pulso', 42.9, 42.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-82620-mkws0sg282di47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F54906291019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
