INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893728184', 'PASTILHA FREIO COBREQ ( N-1806 ) BMW R 1300 / R 1200 / K 1200 / R 1150 / R 850 / YAMAHA FZ15 / R15', 'Pastilha de freio. Marca: Cobreq. Compatível com as motos: Yamaha FZ15 2023 em diante (Dianteira) Yamaha R15 2024 em diante Bmw K 1200 R (Traseira) Bmw K 1300 R (Traseira) Bmw R 1100 S (Traseira) Bmw 1150 (Traseira) Bmw 1200 (Traseira) Bmw 850 (Traseira) Cobreq Linha Racing: Para aplicações de alta performance a linha Cobreq Racing é a escolha ideal, esta aplicação foi especialmente desenvolvida para motocicletas a partir de 500 CC, que necessitam de uma melhor potência de frenagem devido às altas temperaturas, menor desgaste das pastilhas e discos de freio, em sua composição são utilizou materiais de fibra de aramida e kévelar e testado em ambientes extremos de competições como Moto GP, Superbike, Stock Car e F-Truck, garantindo a qualidade e confiabilidade da marca. Código do fabricante: N-1806. EAN: 7892679201221.', 58.8, 58.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhlw2ut7negx24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F23893728184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
