INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998165948', 'Palheta Tradicional 3 para Clarinete Slb Vandoren 2203', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Palheta Tradicional 3 para Clarinete Slb Vandoren 2203 PRODUTO A PRONTA ENTREGA NOVO NA EMBALAGEM ORIGINAL Palheta Tradicional 3 para Clarinete Slb Vandoren 2203 Esta palheta foi concebida para produzir uma qualidade de som extremamente puro, devido a uma ponta de palheta muito fina (a área da palheta que apresenta a máxima vibração), equilibrada com uma coluna vertebral sólida (maior quantidade de cana na área que sobe gradualmente até o calcanhar). Apresenta a ponta mais fina, com o coração mais espesso, resultando numa articulação viva de sonoridade cheia e escura.. Dureza: 3 Material: Cana Espessura da Ponta: 0,09mm Espessura do Talão: 2,8mm', 43.15, 43.15, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbmt-m5iufcx19gn467', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F22998165948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
