INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213783414', 'Conjunto Infantil Menina Moletom Felpado Guloseima', 'Conjunto de moletom para menina que traz blusão com capuz e calça confeccionados em moletom felpado (algodão e poliéster), oferecendo toque macio e conforto térmico. O blusão possui estampa frontal de ursinha com efeito puff, que deixa o visual ainda mais delicado, e acabamentos com elástico no cós, punhos e barras, que contribuem para um ajuste confortável e seguro. Perfeito para compor looks de inverno cheios de praticidade e conforto.Tecido: Moletom FelpadoComposição: Blusão: 50% Algodão 50% Poliéster | Calça: 50% Algodão 50% PoliésterModelo: ConjuntoComprimento Mangas: LongaComprimento: LongoForro: NãoDecote/Gola: Redondo', 224.9, 89.96, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825a1-mqcb0h1m6b6727', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F58213783414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
