INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497834857', 'Pneu Traseiro 140/70-14 68s Pirelli Diablo Scooter S/câmara', 'Pneu Traseiro.: 140/70-14 68S Modelo: Diablo Scooter Reinf Marca: Pirelli Índice de Carga: 68 (315kg) Índice de Velocidade: S (180km/h) Uso: Sem câmara -------------------------------------------------------- Antes de finalizar a compra, confira as medidas que sua moto está utilizando atualmente! Aguardamos a sua compra! -------------------------------------------------------- * NÃO ACOMPANHA RODA -------------------------------------------------------- Garantia de 5 anos somente por defeitos de fabricação, ficando inválida em caso de danos por acidentes, buracos na pista, mau uso e ainda má instalação. É necessário e indispensável instalar o pneu com um profissional especializado.', 626.99, 595.34, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg4249guiqdg68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311725041%2F23497834857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094443206', 'Capacete Moto Fechado Peels Spike 2 Win', 'SPIKE II Conquiste as ruas Spike II Win combina cores vibrantes que capturam a intensidade e a paixão desportiva com um grafismo exclusivo que transmite o espírito competitivo e a energia de um verdadeiro competidor. Tudo isso aliado ao conforto e à segurança já consagrados da Peels. Para quem procura estilo e atitude, Spike II Win é um verdadeiro touchdown na tua coleção. Design moderno e aerodinâmico, com o visual urbano como inspiração. Interior redesenhado para maior conforto. Novo sistema de ventilação com entradas de ar inferior e superior e tecnologia avançada de absorção de impacto para proteção total. Vive essa adrenalina com estilo. O teu rolê é melhor com Peels. Características do produto: Gerais: Revestimento interno termoformado, removível e lavável em tecido antialérgico, com bavete. Produzido no Brasil, com disponibilidade de peças de reposição e fácil manutenção. Peso: 1270 g. Nova guarnição de pescoço, com design moderno e inovador. Segurança: Casco injetado em termoplástico de alta absorção (ABS). Cinta jugular com fecho micrométrico. Testado com a mais alta precisão. Visor: Viseira cristal de 2 mm com tratamento antirriscos. Novo mecanismo de troca de viseira com válvula deslizante de sustentação. Guarnição do campo de visão com melhor vedação. Ventilação: Entrada de ar superior e inferior. Exaustão traseira com remodelagem do casco e spoiler integrado.', 329.9, 329.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-824gm-mer6mqgn78xsec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F740826366%2F22094443206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199259605', 'Leave In Arvensis Reconstrução 200ml', '#html-body [data-pb-style=CLR8ULI]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Leave-In Arvensis Reconstrução 200ml foi desenvolvido para restaurar a estrutura interna dos fios fragilizados, devolvendo resistência e vitalidade. Sua fórmula contém proteínas e aminoácidos reconstrutores, que atuam diretamente na fibra capilar, reduzindo a quebra e o frizz.Com textura leve e ação sem enxágue, o produto protege os cabelos do calor térmico e das agressões externas, mantendo os fios alinhados, macios e com brilho natural. Ideal para cabelos que passaram por processos químicos, escovas ou colorações, garantindo um tratamento contínuo a cada aplicação. Modo de Uso: Aplique uma pequena quantidade nos cabelos limpos e úmidos, distribuindo do comprimento às pontas. Não enxágue e finalize como desejar — com secador, prancha ou secagem natural.', 114.79, 114.79, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-81ztf-midkrak7wxds05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22199259605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
