INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16283178039', 'Balanço Infantil Plástico Cadeirinha de Balanço Reforçado Bebê Criança 1 a 6 Anos Com Corda', 'Balanço ideal para as crianças, bem seguro sem cantos que possam machucar. Material resistente, durável e antitóxico, para ambientes externos e internos. Recomendado para crianças de 18 meses a 6 anos. Cores disponíveis: -Rosa -Azul Itens Inclusos: - Cadeirinha Balanço; - Corda para instalação - 6 metros - Cinto de Segurança reforçado em nylon Especificações Técnicas: - Medidas: 0,28m comp. X 0,35m larg. X 0,35m alt. - Indicado para crianças de 18 meses até 06 anos. - Suporta até 30 Kg. Obs: FAVOR SELECIONAR A COR DESEJADA ANTES DA COMPRA, APÓS A COMPRA NÃO CONSEGUIREMOS ALTERAR A COR QUE SERÁ ENVIADA. IMPORTANTE - Ao instalar verifique antes se esta seguro para evitar acidentes - Não recomenda-se instalar em lugares altos.', 83.75, 73.06, NULL, 'Mom & Baby > Nursery > Bouncers, Rockers & Jumpers', 'https://cf.shopee.com.br/file/9783399d24174cd9dc40aa17baa58889', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F16283178039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45908385298', 'Central Multimidia Etios CarPlay Android Auto Camera de Ré', 'A Multimídia MP5 é a solução completa para quem deseja modernizar o sistema de som e conectividade do veículo. Com tela de 7 polegadas sensível ao toque, oferece navegação rápida e intuitiva, facilitando o acesso às funções essenciais no dia a dia. Compatível com Android Auto e Apple CarPlay via conexão com fio USB, permite integrar o smartphone à central multimídia para utilizar aplicativos como GPS, músicas, chamadas e mensagens diretamente na tela, com mais praticidade e segurança durante a condução. O produto acompanha câmera de ré e moldura para o painel, proporcionando uma instalação mais prática, acabamento perfeito e mais segurança nas manobras, com acionamento automático da câmera ao engatar a marcha ré. Além disso, conta com potência de 4x60W RMS, entregando áudio de qualidade com ótima definição, e diversas opções de conectividade para ampliar sua experiência de entretenimento no carro. Diferenciais do Produto Tela de 7 polegadas Touch Screen de alta sensibilidadePotência de 4x60W RMS com som limpo e potenteCompatível com Android Auto e Apple CarPlay com fio USBEspelhamento de celular com conexão via caboBluetooth para chamadas e reprodução de músicasEntradas USB, SD e AUXCâmera de ré inclusaMoldura para painel inclusa para melhor acabamentoControle remoto para maior comodidadeIluminação lateral com 7 opções de coresDesign moderno que valoriza o interior do veículo Especificações Técnicas Tela: 7 polegadas Touch ScreenPotência: 4x60W RMSIluminação dos botões: 7 cores Conectividade:Android Auto (com fio USB)Apple CarPlay (com fio USB)Espelhamento de celular com fio (consulte compatibilidade) Entradas: USB, SD, AUX e BluetoothEntrada de vídeo: 1Saídas de áudio e vídeo: 2Entrada para câmera de ré: 1Comando de volante (SWC): 2 fios com capacidade de gravação de até 10 funções Dimensões e Peso Altura: 20,5 cmLargura: 15 cmComprimento: 11,1 cmPeso: 0,651 kg Conteúdo da Embalagem 1 Multimídia MP5 2DIN1 Câmera de Ré1 Moldura para painelAcessórios para instalação1 Controle remotoManual de instruções Observação Importante As funções Android Auto e Apple CarPlay funcionam exclusivamente via conexão com fio USB. É necessário conectar o smartphone através do cabo para utilização dos recursos. Não possui conexão sem fio. Especificações Técnicas: É a solução completa para quem deseja modernizar o sistema de som e conectividade do veículo. Com tela de 7 polegadas sensível ao toque, oferece navegação rápida e intuitiva, facilitando o acesso às funções essenciais no dia a dia.', 391.34, 339.43, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-81zu6-mmrmfvg9snpcfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F45908385298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
