INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43028733638', 'Lixeira De Plástico Para Banheiro 6L Preta Automática Oikos', 'Lixeira para Banheiro Oikos 6L Sensor Automático Preto Uma opção prática e higiênica para o seu banheiro. Resumo das Características: Capacidade: 6 litros Material: Polipropileno Dimensões: 14 cm de comprimento x 26 cm de largura x 26 cm de altura Cor: Preto Abertura: Automática (sensor) Local de uso: Banheiros Peso: 0,7 kg Análise: Funcionalidade: Capacidade ideal: 6 litros é uma capacidade adequada para a maioria dos banheiros, acomodando o lixo de forma eficiente. Abertura automática: O sistema de abertura por sensor é higiênico e prático, dispensando o contato manual com a lixeira. Tampa: Evita a proliferação de odores e mantém o ambiente do banheiro mais agradável. Design e Estética: Material leve e durável: O polipropileno é um material resistente e fácil de limpar. Cor versátil: O preto combina com diversos estilos de banheiro, conferindo um visual clean e moderno. Design compacto: As dimensões compactas permitem que a lixeira se adapte a diversos espaços, mesmo os mais reduzidos. Qualidade e Durabilidade: Polipropileno: Material resistente a impactos e fácil de limpar. Instalação e Manutenção: Fácil instalação: Não requer instalação, basta retirar da embalagem e utilizar. Limpeza prática: A lixeira pode ser facilmente limpa com um pano úmido e detergente neutro. Considerações Adicionais: Pontos a Considerar: Baterias: A lixeira requer pilhas para o funcionamento do sensor (não inclusas). Sensibilidade do sensor: A sensibilidade do sensor pode variar e pode ser necessário ajustar a distância de acionamento. Conclusão: A lixeira para banheiro Oikos 6L sensor automático preta é uma excelente opção para quem busca praticidade e higiene. Seu sistema de abertura automático e design compacto a tornam ideal para banheiros de diversos tamanhos. A cor preta traz um toque de leveza e combina facilmente com qualquer decoração.', 199.99, 169.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-81zuo-mkmhzyc3lv5v4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F43028733638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
