INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259655531', 'Café Torrado e Moído Tradicional 3 Corações', 'O Café 3 Corações Tradicional é perfeito para todas as ocasiões, levando à sua mesa um sabor equilibrado e aroma intenso há mais de 40 anos. Desfrute de momentos especiais ao lado de quem você ama com este clássico mineiro de alta qualidade. * Sabor equilibrado e aroma intenso * Vegano e sem glúten * Modo de Preparo: Para cada litro de água, use de 4 a 5 colheres (sopa) de café 3 Corações tradicional. Não deixe a água ferver. Ao primeiro sinal de borbulhas, despeje lentamente a água sobre o pó de café no centro do filtro ou coador, molhando todo o pó. * Para preservar o aroma e o sabor do pó, guarde o pacote em um recipiente fechado.', 34.99, 34.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-82580-mqnem45c96a6c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58259655531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22491810027', 'Trissulfin SID 400mg 10 Comprimidos', '- Indicado para cães e gatos; - Potente antimicrobiano; - Trata infecções urinárias, respiratórias, enterocolite e piodermites; - Também auxilia no tratamento de otites médias e internas, - Disponível em embalagens com 10 comprimidos de 400 mg. O Trissulfin SID é indicado para o tratamento de infecções bacterianas que acometem cães e gatos, causadas pelos agentes Escherichia coli, Klebsiella pneumoniae, Proteus mirabilis, Proteus vulgaris, Staphylococcus aureus, Staphylococcus intermedius, Streptococcus pyogenes, Streptococcus zooepidermicus e Pasteurella multocida, e para o tratamento de isosporoses em cães, causadas pelos agentes Cystoisospora canis e Cystoisospora ohioensis. Contém uma associação entre Ormetoprim e Sulfadimetoxina, os dois antimicrobianos de associação sinérgica, com potencialização da ação da Sulfadimetoxina em decorrência da associação ao Ormetoprim. Modo de usar Administrar o produto por via oral 1 vez ao dia. Uma dose inicial de 160 mg/kg de peso corporal (dose de ataque) no primeiro dia de tratamento. Para os dias subsequentes, administrar a dose de 80 mg/kg de peso corporal. Composição Cada comprimido de 400 mg contém: Sulfadimetoxina .......... 115,00 mg Ormetoprim ............... 23,00 mg Veículo q.s.p............. 400 mg', 65.9, 63.93, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7qvfy-ljd33tg0lcb34f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F22491810027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
