INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43307009605', 'M-vave WP-10 Auscultador de transmissão sem fios 2.4G MS-1 Monitor Sistema Transmissor Recetor Streaming para Estéreo', 'Monitor de auscultadores sem fios de tamanho mais pequeno e mais leve. Tecnologia sem fios 2.4G, baixo atraso, sem compressão. Bateria de lítio recarregável incorporada, 5 longas horas de trabalho, e inclui um cabo USB para um recarregamento cómodo. Ligue o transmissor a um telemóvel ou instrumento musical para utilização e ligue o recetor a auscultadores ou altifalantes para utilização. Suporta um transmissor para enviar sinais a vários receptores. O método de emparelhamento consiste em ligar vários receptores, premir demoradamente o botão de emparelhamento para entrar no modo de emparelhamento de intermitência rápida e, em seguida, ligar o transmissor, premir demoradamente para entrar no modo de emparelhamento, as luzes estão sempre acesas. Suporte para gravação no recetor, pode ligar o transmissor à entrada de linha, como instrumentos musicais, e depois ligar o recetor ao telemóvel para gravar. Suporta estéreo e mono.', 287.0, 136.41, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbp077opav1j25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281436474%2F43307009605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
