INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209038930', 'Pinho Sol Lavanda Desinfetante', 'Pinho Sol Lavanda é o desinfetante ideal para quem busca limpeza, desinfecção e um agradável perfume de lavanda em toda a casa. Elimina 99,9% das bactérias, germes e fungos, garantindo um ambiente protegido e cheiroso. Use em todos os cômodos e em diversas superfícies, como vaso sanitário, ralo, pia, tanque, azulejos e pisos. Rende até 50 litros na limpeza geral.', 19.49, 19.49, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-825aj-mqnekw6pvk0ea7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58209038930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
