INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259496174', 'Conjunto de Agasalho Penalty Pipe – Jaqueta e Calça Esportiva para Treino e Viagem', 'O Conjunto de Agasalho Esportivo Penalty Pipe combina estilo esportivo e casual, sendo ideal para quem busca conforto e versatilidade em dias de temperaturas amenas e frias. Perfeito para o dia a dia, treinos leves ou momentos de lazer, o modelo oferece ótimo caimento e liberdade de movimentos. Confeccionado em malha 100% poliéster, o conjunto proporciona leveza, resistência e conforto térmico. Sua modelagem regular garante ajuste confortável ao corpo, acompanhando os movimentos com praticidade. A jaqueta conta com zíper frontal, gola alta para maior proteção contra o vento, bolsos laterais funcionais e punhos e barra com elástico embutido, proporcionando melhor ajuste. O modelo também possui bordado no peito, além de recortes nas mangas do ombro ao punho com vivo, agregando estilo ao visual esportivo. A calça complementa o conjunto com cós em elástico e cordão interno para ajuste personalizado, bolsos laterais funcionais e bordado na perna esquerda, garantindo praticidade e identidade esportiva. Benefícios: Conforto no dia a dia: tecido leve com ótimo caimento Estilo esportivo: design com recortes e detalhes modernos Ajuste prático: elástico e cordão Versatilidade: uso casual e esportivo', 399.99, 399.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jackets', 'https://cf.shopee.com.br/file/sg-11134201-820mr-mnfsctut6osgc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F58259496174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594082304', 'Kit 2 Pneus 275/65R18 LT 10 Lonas 123/120R Brutus TA Xbri', 'Kit 2 Pneus 275/65R18 LT 10 Lonas 123/120R Brutus TA Xbri O pneu Xbri Brutus chegou para revolucionar o mercado de pneus off-road para caminhonetes. Com letras brancas preenchidas, carcaça LT e laterais bem reforçadas, ele foi feito para entregar durabilidade excepcional, excelente tração em pisos irregulares por conta dos sulcos profundos da banda de rodagem. Marca: Xbri Modelo: Brutus TA (Borrachudo) Pneu LT = Light Truck, usado em caminhonetes ou caminhões de pequeno porte Aro: 18 Índice de peso (por pneu): 123 - 1550Kg Índice de peso (rodado duplo): 120 - 1400Kg Índice de velocidade: R - 190Km/h Construção: Radial Tipo: Sem camara Aplicação: Todo terreno Tipo de desenho: Simetrico Lateral: Letras Brancas', 2277.6, 2277.6, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7ratw-maoabvc09boi87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F23594082304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094422597', 'RUM HAVANA CLUB 7 ANOS 700ML', 'O processo de criação do Havana Club 7 anos leva mais de 14 anos, embora a idade mínima para qualquer rum na mistura seja de 7 anos. Isso se dá pelo método criado por Don Jose Navarro, onde uma parte final de cada barril de rum é devolvido para maturar novamente até que esteja pronto para compor o próximo lote de Havana Club 7 anos. O sabor do rum é uma viagem por Cuba, desde o mundialmente famoso tabaco cubano, passando pelo rico e doce das frutas, até o sabor de especiarias e baunilha fruto do processo de envelhecimento, além do principal ingrediente, a cana de açúcar. Pela complexidade de sabores do Havana Club 7 anos ele é melhor apreciado puro e bem gelado. Fundado em 1878 por José Arechabala, o Havana Club é um símbolo da tradição e cultura cubana.', 219.9, 210.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mefthsol91c15e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22094422597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22320270437', 'Chuteira Society Penalty Matis Kids Xxi', 'A Chuteira Society Penalty Matis Kids XXI é ideal para jovens atletas que buscam desempenho, conforto e segurança nos gramados sintéticos. Com design moderno e tecnologias exclusivas, o modelo oferece tração precisa, flexibilidade e estabilidade para cada jogada, permitindo que os pequenos dominem o jogo com confiança e estilo. Benefícios: Desenvolvida especialmente para partidas em quadras society. Conforto e flexibilidade para maior liberdade de movimento. Solado com mini-cravos que garantem tração e estabilidade. Material resistente e durável, ideal para o uso frequente. Auxilia na prevenção de lesões durante os treinos e jogos. Diferenciais Técnicos: Cabedal: Micropower – mais leveza e resistência. Tecnologia Rotate: pontos de giro que facilitam mudanças rápidas de direção. Tecnologia Hiperflex: canaletas que auxiliam na flexão do pé para arrancadas explosivas. Palmilha: EVA plana de 3,5 mm para conforto extra. Solado: Borracha com alta aderência e durabilidade.', 169.99, 169.99, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-823oh-mozu9o3gbnkdc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F22320270437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43526492169', 'Chuteira Umbro Society Neo Comfort Preto e Branco - Masculino', 'Parte superior do formulário Mais domínio e conforto em cada jogada! Chuteira Umbro Society Neo Comfort Preto e Branco - Masculino Parte superior do formulário Ficha Técnica: Marca: Umbro Cor: Preto e branco Cabedal: Sintético resistente com ajuste anatômico; biqueira em camurça Forro: Poliéster respirável Palmilha: EVA com amortecimento suave Sola: TPU e EVA Fechamento: Cadarço Amortecimento: Médio Estabilidade: Neutro Tecnologias: Breeze System, pontos perfurados posicionados para proporcionar uma melhor ventilação Indicação: Futebol Society (gramado sintético) Detalhes: Logo Umbro nas laterais e no calcanhar, cabedal sintético durável, forro em poliéster para respirabilidade e solado com dupla densidade para melhor tração Desenvolvida para o jogo de alto rendimento, a Chuteira Umbro Neo Comfort proporciona ajuste firme, respirabilidade e excelente tração nos gramados sintéticos. Porque investir: O solado com combinação de TPU e EVA oferece estabilidade e resposta rápida nos movimentos, enquanto o cabedal sintético garante resistência ao desgaste. Sinta a leveza e a segurança em cada passo e leve seu desempenho a um novo nível. Conteúdo da embalagem: 1 par de Chuteira Umbro Society Neo Comfort Preto e Branco - MasculinoParte superior do formulário Parte superior do formulário Parte superior do formulário', 359.99, 291.99, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-821ec-mh66qv3971fz36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F43526492169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
