INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998783691', 'Blusa Feminina Texturizada Decote V Marialícia Preto', 'A Blusa Marialícia é uma peça coringa para composições elegantes e confortáveis. Feita em tecido texturizado, ela possui comprimento regular, mangas curtas e caimento soltinho, proporcionando leveza ao visual. O decote V com detalhe em prega valoriza o colo, enquanto seu design minimalista garante versatilidade. Perfeita para composições casuais e sofisticadas, pode ser usada com calças, saias ou shorts. Invista nesse look que se adapta a diversos estilos e ocasiões.Modelo veste G1 Medidas da modelo: 111cm de busto; 122cm de quadril; e 96cm de cintura', 89.9, 35.96, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-82597-mr1tixvglslo92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23998783691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
