INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497665447', 'Kit 4 Cadeira Leda Branca Charles Eames Wood Com Almofada', 'Kit Com 4 Cadeira Leda Branca - Charles Eames Wood Com Almofada Cadeira Leda Charles Eames Wood Do designer finlandes Eero Saarinen, a cadeira com assento estofado Saarinen representa um trabalho icônico de design da década de 50, juntamente com a Eames. Sua concha ergonômica é produzida em PP (Polipropileno) e conta com assento fixo em tecido sintetico (PU). Seus pés são feitos em madeira com ótimo acabamento. Adequa-se perfeitamente para compor conjunto de mesa de jantar ou qualquer outro ambiente em sua casa ou escritório. Ideal para receber amigos e familiares com um toque de elegância e charme. Especificações Técnicas: Material da Estrutura: Madeira Material do Assento: Polipropileno Material da Almofada: Revestimento Sintético Garantia de 3 meses por defeito de fabricação. Altura Total: 82 cm Altura do Chão Até o Assento: 47 cm Profundidade Interna do Assento: 45 cm Largura Interna do Assento: 49 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 4,40 kgs Não Giratória Não Dobrável Não Empilhavel Indicações de Uso: - Não utilizar produtos químicos e abrasivos para limpeza - Limpar com pano umedecido e sabão neutro para melhor conservação - Deve ser evitada exposição dos produtos ao sol pois podem apresentar pequenas mudanças em sua coloração. Observações importantes: - Produto Enviado: Desmontado - Complexidade de Montagem: Fácil - Manual de Montagem: Acompanha o produto - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. - O produto é enviado desmontado. Portanto, necessita montagem após recebimento.', 756.0, 756.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvi-ly5lrtfegw2q4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23497665447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
