INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197977383', 'Par Pivô Suspensão Dianteiro Nakata Logan Sandero 2013 2020', 'Este anúncio contem os seguintes produtos: 01 (UM) Pivô da Bandeja suspensão Dianteira Direita Nakata; 01 (UM) Pivô da Bandeja suspensão Dianteira Esquerda Nakata; Atenção: Produtos Novos e Originais, com 3 meses de garantia total, a pronta entrega. Código do produto: N99332. Aplicação dos Veículos: Veículo: Logan; Motor: 1.0 12v, 1.6 16v, 1.6 8v; Ano fabricação: 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020; Veículo: Sandero; Motor: 1.0 12v, 1.6 16v, 1.6 8v, 2.0 16v; Ano fabricação: 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020; Dúvidas frequentes: O Produto é novo? Sim, nós trabalhamos apenas com produtos novos e originais com garantia. O Produto é original? Sim, nós só trabalhamos com distribuidores representados pelos fabricante, ou compramos diretamente dos fabricantes, gerando confiança da originalidade do produto. O produto é igual ao da foto? Sim. Todas as fotos são fiéis ao que você irá receber, e para facilitar a sua compra ilustramos também o veículo em que se aplica o produto. Em quanto tempo recebo minha compra? É muito simples, basta colocar seu CEP no calculador de frete do anuncio. Como faço para saber se o produto deste anúncio se aplica ao meu veículo? Você pode conferir se o produto se aplica no seu carro através da descrição do anúncio no item: “Aplicação dos Veículos”. Caso tenha alguma dúvida, entre em contato com nossa equipe e os profissionais qualificados irão te orientar em qualquer dúvida, estamos sempre a disposição. Tem alguma dúvida sobre o produto ou sobre a compra? Deixe sua pergunta abaixo, que responderemos prontamente. O que é: O pivô de suspensão é uma peça fundamental do sistema de suspensão de um carro, localizada na extremidade da bandeja ou braço da suspensão. Sua principal função é permitir que a suspensão se mova para cima e para baixo, acompanhando as irregularidades do terreno, enquanto mantém a roda alinhada com a carroceria. Isso ajuda a garantir estabilidade, conforto e segurança ao dirigir, pois o pivô permite que a roda gire e se mova verticalmente, mantendo o contato com o solo. Um pivô de suspensão desgastado ou danificado pode causar barulhos, vibrações e comprometer a dirigibilidade do veículo, sendo importante verificar e substituir essa peça conforme necessário.', 201.54, 201.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8ey0i09o7ptd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287764105%2F19197977383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48758137460', 'Garrafa Modus Térmica 750ml Aço Inoxidável Com Alça Paracord Garrafa Térmica Café', 'Marca: MODUS Aventura, treino ou dia a dia: a MODUS 750ml acompanha você! Se você vive em movimento, precisa de uma garrafa térmica à altura. A MODUS foi feita para quem não abre mão de uma bebida gelada depois do treino ou de um café quente durante a trilha. Por que levar a MODUS na sua próxima aventura? Trilha: Alça de paracord para prender na mochila Academia: Capa antiderrapante – adeus garrafa escorregando! Viagem: 24h de gelo – perfeito para dias quentes Trabalho: Design elegante que combina com qualquer look E mais: Leve (400g) e compacta (28cm de altura) Resistente a arranhões e quedas Livre de BPA – puro sabor, sem química MODUS: sua parceira de todas as horas.', 179.98, 49.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820mb-moayfpojk7466d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F534109767%2F48758137460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
