INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254091353', 'Kit 40 cápsulas Espresso Intenso - Nescafé Dolce Gusto', 'Leve o Espresso Intenso NESCAFÉ® Dolce Gusto® no kit 4x10 (40 cápsulas) para um boost de sabor a qualquer hora. Intensidade 7, perfil forte & vibrante, em espresso curto de 40 ml com crema marcante. Pronto em segundos nas máquinas Dolce Gusto – linha Original, sem sujeira e com padrão de cafeteria. Mais rendimento no combo: 40 doses para quem prefere um espresso potente no dia a dia.', 99.6, 66.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8261b-mjypdv7mu8ef35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1531827759%2F58254091353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
