INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206298558', 'Extrator de Frutas Premium Turbo E10 250W Mondial', 'O Extrator de Frutas Premium Turbo E10 Mondial tem 250W de potência e copo de 1,25 L para você preparar com mais rapidez e eficiência seu suco natural de fruta. Ele possui duas castanhas de diferentes tamanhos para você ter o melhor encaixe e absorver todo o suco da fruta, seja de laranja ou limão. Simples e eficiente de usar e fácil na hora de limpar! Características: Fácil de usar Corpo em aço inox 1 Copo superior 1 Peneira 2 Castanhas de diferentes tamanhos para extração de suco de laranja e limão Motor com duplo rolamento blindado e proteção térmica Coador Copo superior acoplado Guarda-fio que permite ajustar o tamanho do cabo Motor com dupla rotação: sim Acessórios: - 01 Copo de 1,25 L- 02 Castanhas de tamanhos diferentes- 01 Coador Capacidade da jarra: 1,25 L Consumo de energia: 0,25 kW/h Potência: 250W Tipo de Tomada: 10A (4mm) Tipo de Plugue: 2 Pinos Conteúdo da Embalagem: 1 Extrator de Frutas Premium Turbo E10 250W Mondial Manual de instruções Garantia do Fornecedor: 12 meses Atenção: Verifique a voltagem do produto. Fotos meramente ilustrativas. Demais produtos que não fazem parte do conteúdo da embalagem, são ilustrativos e não são vendidos com o produto. Não nos responsabilizamos pela instalação ou montagem; também não nos responsabilizamos pelo transporte por escadas, elevadores, guincho ou içamento deste produto. Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto', 189.9, 189.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-82611-mlgebifxw0lg27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58206298558', NULL, NULL, '2