INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792809652', 'Lixadeira Esmerilhadeira Eletrica 850w Politriz Esmerilhadora Potente Com Acessorios', 'Esmerilhadeira Angular 850W – Esmerilha, Lixa e Politriz ⚡ Potência, Versatilidade e Alto Desempenho para Seus Projetos! A Esmerilhadeira Angular 850W com Função Politriz foi desenvolvida para quem busca praticidade, eficiência e excelentes resultados em cortes, desbastes, lixamentos e polimentos. Com motor potente de 850W e velocidade de até 11.000 RPM, oferece desempenho superior para trabalhos profissionais e domésticos. Seu design compacto e ergonômico proporciona maior conforto durante o uso, enquanto o sistema de ventilação otimizado ajuda a manter o motor refrigerado, aumentando sua durabilidade e eficiência. ✅ Principais Diferenciais ✔ Motor de alta potência com 850W ✔ Função 3 em 1: Esmerilhadeira, Lixadeira e Politriz ✔ Velocidade de até 11.000 RPM ✔ Ideal para cortes, desbastes, lixamentos e polimentos ✔ Empunhadura lateral para maior firmeza e controle ✔ Trava de eixo para troca rápida dos discos ✔ Protetor de disco para mais segurança durante o trabalho ✔ Estrutura resistente e durável ✔ Indicada para uso profissional e doméstico 🔧 Aplicações ✅ Corte de metais, ferro e aço ✅ Desbaste e acabamento de superfícies ✅ Lixamento de madeira e outros materiais compatíveis ✅ Polimento de peças e superfícies ✅ Oficinas, serralherias, construção civil e manutenção em geral 📋 Especificações Técnicas Potência: 850W Frequência: 50/60Hz Rotação Máxima: 11.000 RPM Diâmetro do Disco Compatível: 115 mm Comprimento do Cabo: 2 metros Alimentação: Elétrica 📦 Conteúdo da Embalagem 1 Esmerilhadeira Angular 850W 1 Empunhadura Lateral 1 Chave de Aperto 1 Protetor de Disco 1 Maleta de Soquete 💪 Tenha em mãos uma ferramenta robusta, versátil e eficiente para realizar seus trabalhos com mais precisão, segurança e produtividade.', 229.9, 139.13, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lj-mpmoxvocmcch82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356560587%2F22792809652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099453781', 'Meião Penalty Se7e Preto e Cinza', 'TecnologiasFlot: Tecnologia exclusiva de construção de pontos mais amplos do que o padrão, além de trazer leveza na meia que melhora a performance do jogador efavorece a evaporação do suor, garantindo o equilíbrio térmico.Dry One: Tecnologia que garante a rápida absorção e o transporte do suor para as camadas externas da meia, proporcionando uma secagem mais rápida e deixando os pés secos.Confort: Sola atoalhada que transmite maciez e conforto, evitando a formação de bolhas.Anatomic: Modelagem que se ajusta perfeitamente aos pés, proporcionando maior conforto.Compress: Faixa tensora com função de dar compressão, fornecendo um ajuste perfeito e total liberdade dos movimentos durante as atividades físicas.Contém: 01 parComposição: 22,51% Algodão, 4,43% Poliamida, 18,51% Elastodieno, 23,84% Elastano e 30,71% PolipropilenoCor predominante: PretoTamanho único: 39 - 44Peso aproximado: 50 gIndicado para: JogoOrigem: Nacional', 37.9, 37.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-m0k5fiat7pmi60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F19099453781', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
