INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299159108', 'Espelho Retrovisor Interno Original Renault', '7700413867 Espelho Retrovisor Interno Original Renault. OBSERVACOES: Vendido e entregue por Grupo Estoril Renault. Antes de efetuar a compra tire todas suas dúvidas no campo perguntas Caso precise de informações sobre aplicação, sempre informe o n° de Chassi ou placa do Veículo, que se encontra no documento. Mantenha seus dados e endereço atualizado no site do Shopee. Envio para fora do Estado de São Paulo efetue a compra com CPF, nao enviamos para CNPJ. Peca nova original com NF-e. ATENCAO: - Antes de efetuar a compra tire todas suas dúvidas no campo perguntas. - Mantenha seus dados e endereços atualizados no site do Shopee. - Se o parceiro logístico nao entregar seu produto, seu pagamento sera devolvido automaticamente pelo Shopee. - Temos carrinho de compras, adicione vários produtos e economize no Frete. - Todos os produtos anunciados estão disponíveis em nosso estoque. - Aceitamos devoluções apenas com a embalagem Original e Nota Fiscal. - Devido a alteração nas políticas do Shopee o frete grátis está sujeito ao peso, preço e distância do envio. ________________ SUPORTE E HORARIOS DE ATENDIMENTO: - Temos Equipe de Atendimento e Suporte Técnico Especializado a Disposição. - Atendimento de Seg. a Sex. das 8h00 às 18h00 e Sab. 8h00 as 12h00. ________________', 55.62, 55.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdwb-mbyub8q1vk2t10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1383285516%2F23299159108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51610451953', 'Kit 2 Cobertores Manta Fleece Queen Microfibra Hipoalergênica', 'A Manta de Microfibra Fleece foi desenvolvida para proporcionar conforto, praticidade e aconchego em diferentes momentos da rotina. Com toque aveludado, ela envolve o corpo com suavidade e aquece. É uma peça leve e fácil de lavar, sendo uma excelente escolha para a cama, o sofá, home office ou para acompanhar viagens. Produzida em microfibra de alta qualidade, a peça é respirável e hipoalergênica, oferecendo uma sensação agradável ao toque sem pesar. Seu tecido fleece contribui para um acabamento mais aconchegante, enquanto a secagem rápida facilita os cuidados do dia a dia. Além de confortável, é prática e resistente: não amassa com facilidade e mantém a cor vibrante mesmo após várias lavagens. O acabamento reforçado nas bordas ajuda a preservar a estrutura da peça por mais tempo, garantindo melhor durabilidade no uso diário. Diferenciais: Toque aveludado: tecido fleece macio e agradável no contato com a pele Microfibra de alta qualidade: leve, confortável e resistente Hipoalergênica: desenvolvida para oferecer bem-estar no uso diário Leve e respirável: aquece sem pesar e permite melhor circulação do ar Secagem rápida: mais praticidade após a lavagem Fácil de cuidar: seca rápido, não amassa e não desbota Acabamento reforçado: costura nas bordas para maior durabilidade Diversas cores: opções para combinar com diferentes estilos de decoração Características: Tamanho: Queen Marca: BF Colchões Modelo: Fleece Material: Microfibra fleece em poliéster hipoalergênica Medidas do tamanho Queen: 220cm x 200cm Conteúdo de Embalagem: 02 Mantas Queen Observações!!! Imagens meramente ilustrativas. Os objetos que ambientam as fotos não acompanham o produto. Atenção: As cores do produto podem sofrer pequenas variações devido à configuração da tela do seu dispositivo. Lavar em ciclo leve, não misturar cores claras e escuras, utilizar sabão neutro, não usar alvejantes, seguir sempre as instruções da etiqueta do produto', 174.2, 122.9, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/br-11134207-820mg-mo6yrn8kh14wf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264071501%2F51610451953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
