INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16557456408', 'Farinha D Agua ou Farinha do Pará 1Kg', 'A farinha d''água é um tipo de farinha de mandioca fermentada, tradicional da região Norte do Brasil. Ela passa por um processo de hidratação e fermentação natural, o que dá um sabor levemente azedo e uma textura mais granulada. Muito usada em pratos típicos como o pirão, a farofa e acompanhamentos regionais. Ingredientes: Mandioca. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 13.67, 13.67, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqp6w5o0tyxre9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F16557456408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
