INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399257316', 'Pneu Goodyear Aro 17 Wrangler Territory HT 235/65R17 108H XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Goodyear A marca Goodyear Considerada uma das maiores marcas de pneus no mundo, a Goodyear possui 2 centros de inovação, 48 fábricas e está presente em 22 países. Fundada por por Frank Seiberling em Akron, Ohio (EUA), já últrapassou os 100 anos de existência e hoje em dia conta com mais de 64 mil colaboradores no mundo todo. Investindo constantemente em inovação para fabricar pneus para automóveis, caminhões comerciais e leves, utilitários esportivos, carros de corrida, aviões e máquina agrícolas, é líder de vendas no mercado norte americano.', 1283.22, 1180.57, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd55-lvkft52aqiqr5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20399257316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
