INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697117417', 'Kit 6 Caixas de Som Acústica JBL C621P Passiva Preta - 50 Watts RMS', '06 Caixas De Som C621 P Jbl Selenium Ambiente C621p A Caixa Acústica Jbl Selenium Ambientare C621P duas vias compactada, A Caixa Jbl Selenium C621P é ideal para sonorização ambiente. Fácil instalação e ótima integração com o ambiente. Injetada em plástico e tela frontal em alumínio. Versátil e funcional. Desfrutar de um amplo espectro de sons, até mesmo os mais agudos, é possível com esta caixa de som woofer, tweeter. Você sentirá a diferença na excelente qualidade de som. O woofer é acoplado através de um divisor de frequências interno, especial para cada modelo, desenvolvidos com componentes de alta fidelidade. A forma da Caixa Acústica Som Ambiente 50W C621B JBL sem paredes paralelas propicia uma resposta em frequência plena e suave. São duas excelentes caixas para som ambiente. Garanta já a sua! Especificações Técnicas: • Potência: 50W Rms (Cada Uma) • Impedância: 8 Ohms • Resposta de Frequência: 85Hz - 20KHz • Alto Falante de: 6 (Polegadas) • Tweeter de: 1 (Polegada) • Tipo: Caixa Acústica • Sensibilidade: 90 dB spl • Cor: Preta • Peso: 3,225 kg Conteúdo da Embalagem: • 06 Caixas Som Acústica Jbl C621P Preta • Manual e Certificado de Garantia Importante: • Garantia de 273 dias. • Valor do Kit.', 3688.36, 3467.06, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-lnvenzoi3c0c38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F23697117417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
