INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28030190957', 'Prato para Risoto Wolff Scallop de Cerâmica Azul 23cm', 'Prato para Risoto Wolff Scallop de Cerâmica Azul 23cm Sirva seus pratos favoritos com estilo e sofisticação com o Prato para Risoto de Cerâmica Azul da Wolff. Com um design elegante e moderno, este prato é perfeito para realçar a apresentação de suas deliciosas receitas. Design EncantadorCom sua cor azul vibrante e acabamento delicado, este prato adiciona um toque de charme à sua mesa, tornando-se uma peça de destaque em qualquer ocasião. VersatilidadeCom um tamanho de 23cm, este prato é ideal não apenas para risotos, mas também para uma variedade de pratos, desde massas até saladas e sobremesas, tornando-o uma adição versátil à sua coleção de louças. Qualidade PremiumFabricado em cerâmica de alta qualidade, este prato é resistente e durável, garantindo sua beleza e funcionalidade por muitos anos. Transforme suas refeições em momentos especiais com o Prato para Risoto de Cerâmica Azul da Wolff. Adquira já o seu e adicione um toque de elegância à sua mesa. Wolff - A melhor experiência em receber, servir e decorar. Contém: 1 Prato para Risoto Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 5,00cm x Largura 23,00cm x Comprimento 23,00cm Peso: 0,73Kg Cor: Azul Material: Cerâmica Lavar com detergente neutro, esponja macia e secar imediatamente.', 73.0, 51.99, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rd51-m7ibuyso0i3t4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F28030190957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
