INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53859967735', 'Tenis Democrata Masculino Draft Pulse Couro Confortavel', 'Democrata Draft Pulse 635101: A energia que falta no seu visual casual. O Tênis Democrata Draft Pulse redefine o conceito de calçado híbrido. Combinando a nobreza do couro legítimo com uma entressola inspirada na alta performance esportiva, ele é ideal para o homem que não para. O grande destaque deste modelo é o solado robusto com textura que lembra grânulos de amortecimento, garantindo um caminhar extremamente macio e um retorno de energia superior para o dia a dia agitado. Diferenciais que garantem a performance: Couro de Alta Qualidade: Cabedal robusto em couro legítimo que oferece durabilidade e um visual sofisticado. Tecnologia Pulse: Entressola volumosa desenvolvida para absorver impactos e proporcionar conforto prolongado. Solado Bicolor: Base em borracha antiderrapante que garante estabilidade e segurança em diferentes superfícies. Puxador Traseiro: Detalhe funcional que facilita o calce e adiciona um toque moderno ao design. Detalhes Refinados: Logo Democrata discretamente gravado na lateral e microperfurações no bico para auxiliar na ventilação. Ficha Técnica Detalhada: Marca: Democrata (Original) Linha: Draft Pulse Referência: 635101-001 Material Externo: Couro Legítimo TABELA DE MEDIDAS 37 - 26 38 - 26,5 39 - 27,5 40 - 28 41 - 28,5 42 - 29,5 43 - 30 44 - 30,5 Tênis Democrata, Democrata Draft Pulse, Tênis de Couro Masculino, 635101-001, Tênis Amortecimento Masculino, Sapato Casual Couro, Democrata Original, Tênis Pulse Preto, Calçado Masculino Premium.', 429.9, 349.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820m6-mowwuwssz2mea2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F591297390%2F53859967735', NULL, NULL, '2026-07-28T0