INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23132550580', 'Pack Shamp. + Cond. -2 Litros - Super Bonita - Probelle', 'KIT SHAMPOO E CONDICIONADOR 1L + 1L Shampoo e Condicionador Limpeza delicada e suave, com efeito brilho espelhado e movimento natural. Foi especialmente desenvolvida para garantir o fortalecimento, hidratação e controle de frizz dos cabelos. Fórmula sofisticada e luxuosa com ação energizante, doa sedosidade e nutrição, combate o ressecamento. Esse produto ainda permite que você dê aos fios uma dose de brilho extra e mais volume nos cachos graças ao poder dos seus 6 Óleos. Condicionador de máximo desempenho, com efeito ultra condicionante e desembaraçante. Foi especialmente desenvolvida para garantir o fortalecimento, hidratação e controle de frizz dos cabelo.', 48.9, 38.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbm7-lofvqktcigake6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F23132550580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998004054', 'MANGUEIRA PARA JARDIM SUNFLEX TRANÇADA COM ADAPTADOR 1/2 E 3/4 - VÁRIOS TAMANHOS', 'VOCÊ RECEBERÁ: 1 Mangueira para Jardim A mangueira trançada Sunflex vai facilitar as tarefas do seu dia a dia! Conte com maior flexibilidade e agilidade para utilizá-la em seu jardim ou quintal. Inclui adaptador para para torneira de jardim e ponta com esguicho para facilitar o uso. A Mangueira Jardim Trançada Flex, foi desenvolvida para facilitar as mais diversas tarefas, tanto para atividades domésticas como para atividades profissionais. É possível irrigar o jardim pela superfície ou até mesmo pelo subsolo, Banhos em cães, Lavagem em carros, adaptado para qualquer torneira padrão ... Para ter uma boa durabilidade, é preciso ter alguns cuidados e sempre guardar a mangueira de jardim higienizada. Sendo ideal não deixa a mangueira exposta as mais diferentes condições climáticas, como chuva e sol. Informações gerais e recomendações - Para condução de água fria - Evite dobras ao enrolar a mangueira - Para aumentar a durabilidade da mangueira, não deixá-la exposta ao sol após o uso - Para uso doméstico ou profissional na jardinagem, em situações com pressão da água de até 18 bar [261 psi] Espessura: 7/16"', 57.14, 57.14, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reo4-m28hhjtorxz042', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F23998004054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
