INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58214252717', 'Bardahl Flex Condicionador de Metais Kit Anticorrosivo', 'Oferece uma manutenção preventiva completa para veículos flex, atuando em duas frentes fundamentais para aumentar a vida útil do veículo: o sistema de alimentação (protege bicos injetores e válvulas contra a corrosão do etanol e da gasolina, mantendo o sistema limpo e lubrificado) e as peças metálicas internas (forma um filme protetor antidesgaste em regimes severos de atrito, como motores, mancais e rolamentos).', 59.9, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnqfq8hgl5a88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1819345424%2F58214252717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
