INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598090737', 'Kit Shampoo + Condicionador + Máscara CACHOS - Probelle', 'Shampoo Cachos Definidos Ação: Shampoo com fórmula luxuosa e sofisticada. Máxima definição de cachos. Máxima formação de cachos Resultado: Aumento da elasticidade, brilho excepcional e poder antioxidante com efeito de longa duração. Condicionador Cachos Definidos Ação: Máxima definição de cachos. Máxima formação de cachos. Desenvolvido com altíssima tecnologia e formulado especialmente com matérias primas de baixíssimo peso molecular. Resultado: Penetra com maior facilidade atuando em profundidade, proporcionando um resultado surpreendente, com nutrição absoluta. Máscara Cachos Definidos Ação: Maximiza a formação de cachos, aumenta o volume e o brilho espelhado. Resultado: Finalização de altíssimo desempenho. Desembaraça, dá brilho e movimento natural com ação anti radicais livres. SHAMPOO CACHOS SENSACIONAIS Ação: Limpeza suave com máxima proteção contra o ressecamento. Brilho com toque macio. Resultado: Máximo volume com nutrireparação e ação energética. Desembaraça, dá brilho e volume com ação anti radicais livres. CONDICIONADOR CACHOS SENSACIONAIS Ação: Condicionador com máxima ação energética capilar. Protege contra o ressecamento. Fórmula sofisticada e luxuosa. Resultado: Resultado de longa duração. Promove filme protetor que impede a entrada ou a saída da umidade natural. Toque macio e sedoso. MÁSCARA CACHOS SENSACIONAIS Ação: Previne o aparecimento de pontas duplas. Promove movimento natural e máximo volume com ação proteção térmica. Resultado: Protege contra o ressecamento. Com nutrireparação e ação energética capilar. Desembaraça, dá brilho e hidrata. Resultado de longa duração.', 53.9, 33.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-82617-ml6cq06hpa0w37'