INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18661906265', 'Filtro Ar Volkswagen Fox Golf Polo 1.6 16v 2014 A 2019 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação - Fox 1.6 16V 2014 a 2018. Golf Comfortline 1.6 16V 2016 a 2018. Polo MSI 1.6 16V 2017 a 2019. Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001, certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. Importante Tempo de garantia - 3 meses. Imagem meramente ilustrativa. Valor unitário. Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 7798186475110 Código do Fabricante FAP2219 >', 30.9, 30.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7r9ad-lluicrutkvtv7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18661906265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
