INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798198531', 'Armário de Cozinha Compacta 190cm Branco Reims Madesa 04', 'A linha de Cozinhas Reims da Madesa une modernidade e elegância. Composta por três módulos avulsos, possui materiais de alta qualidade, como corrediças e dobradiças metálicas, puxadores embutidos de alumínio e pés de madeira maciça. O espaço é amplo, ideal para louças, panelas e utensílios. O balcão acompanha tampo em MDP e pode ser removido para instalação de pia com espaço de 120 x 52 cm. Para completar, possui acabamento branco de alta resistência. Medidas totais: - 190 cm de largura - 210 cm de altura - 52 cm de profundidade no balcão e e 31 cm nos aéreos Itens inclusos: - Um (1) Armário Aéreo de 70 cm com uma (1) porta basculante - Um (1) Armário Aéreo de 120 cm com duas (2) portas - Um (1) Balcão de 120 cm com duas (2) portas, uma (1) gaveta e tampo Código do produto: GRRM19000409 Obs.: - A Madesa não disponibiliza serviço de montagem - O produto segue com manual e todas as ferragens necessárias para a instalação - Imagens meramente ilustrativas, os eletros e as decorações não acompanham o produto A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 1039.99, 858.68, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rcf9-m65ge1h1w787ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F22798198531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
