INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193335971', 'Kit 12 Unidades Refil Pincel Para Quadro Branco Preto Pilot V Board Master', 'Refil Pincel para Quadro Branco Preto Pilot - Caixa com 12 Unidades Renove seu Pincel para Quadro Branco com o Refil Pilot na cor preta - qualidade superior e preço acessível! Cada traço é uma expressão de excelência, proporcionando uma escrita suave e duradoura. Não sacrifique seu orçamento: escolha a Pilot para uma experiência única, unindo qualidade premium e preço acessível. Transforme seus momentos criativos com o Refil Pincel Quadro Branco Pilot. Especificações técnicas: Marca: Pilot Referência: 2450006CX012PR Características do Produto: Refil Pincel para Quadro Branco Preto Pilot - Caixa com 12 Unidades Embalagem: Caixa com 12 Unidades Com mais de 70 anos de tradição no mercado, a Jandaia é referência nacional na produção de materiais escolares e de escritório. Reconhecida pela qualidade, criatividade e compromisso com a educação, a marca se destaca por oferecer produtos que aliam funcionalidade, design moderno e durabilidade. Presente no dia a dia de milhões de brasileiros, a Jandaia investe constantemente em inovação para atender às necessidades de crianças, jovens e adultos, criando itens que estimulam a organização, a escrita e o aprendizado. Do universo escolar ao ambiente profissional, a Jandaia está presente em cada detalhe com excelência e confiança. Escolher produtos Jandaia é optar por uma marca com história, responsabilidade e dedicação à criação de soluções práticas e inspiradoras para todas as fases da vida.', 171.52, 171.52, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-7rdyw-m0ixkqdjo0xc5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F23193335971', NULL, NULL, '2026-