INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898847673', 'Dom Quixote - Edição de Luxo', 'Dom Quixote, escrito pelo espanhol Miguel de Cervantes, é umclássico da literatura mundial e uma das obras mais influentesda história. Publicado pela primeira vez em 1605, o romance éuma obra-prima da ficção que tece uma narrativa na qual humor,drama e filosofia são mesclados a personagens complexos eemocionantes. A história gira em torno de Alonso Quijano, umfidalgo empobrecido que decide se tornar um cavaleiro errante edefender os oprimidos. Vestido com uma armadura antiga, dá a simesmo o nome de Dom Quixote e parte em busca de aventurasacompanhado por seu leal escudeiro, Sancho Pança. Enquantonarra a luta de Dom Quixote para reconciliar seus sonhos idealistascom a realidade do mundo em que vive, Cervantes traz à tonaquestões profundas de identidade, loucura, amor e amizade,convidando o leitor a profundas reflexões acerca do mundo e desi mesmo, além de incentivar a busca pelos sonhos e ideais, aindaque pareçam loucos aos olhos alheios. DESCRIÇÃO DO PRODUTO: ISBN13: 9786584956261 Páginas: 864 Publicação: 1ª Edição - 2023 | Editora Garnier Encadernação: Capa Dura Formato: 15,5 x 23,0 cm Autor: Miguel Cervantes', 199.0, 89.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m65sl19960ed3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F20898847673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
