INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798376532', 'Camisa Vasco da Gama 74 Retrô', 'A camisa retrô do Vasco da Gama é a escolha perfeita para os torcedores vestirem sua paixão pelo Gigante da Colina em todos os momentos. O manto faz homenagem ao ano de 1974, quando o time tornou-se o primeiro clube carioca a ser campeão brasileiro. A peça é confeccionada com fibras de algodão macio e confortável e o design foi inspirado no manto utilizado naquele ano, sendo predominantemente preto com detalhes em branco, como a faixa diagonal vista na parte da frente. Além disso, a tradicional Cruz de Malta ganha destaque bordada do lado esquerdo do tórax. Por fim, o punho das mangas possui acabamento canelado, assim como a gola, que por sua vez, é V. Adquira já! Composição: 100% Algodão Origem: Nacional Escudo: BordadoManga: CurtaGola: VDimensão aproximada (A x L):P: 69 x 54 cmM: 71 x 56 cmG: 73 x 58 cmGG: 75 x 60 cmEG: 77 x 62 cm', 174.9, 174.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-7req7-m8as1h76zq2ocb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22798376532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
