INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23095028577', 'Eudora Niina Secrets Soft Petals Paleta de Sombras 10g', 'A Paleta de Sombras Niina Secrets Soft Petals é o acessório de make ideal para mulheres que desejam transformar o olhar com sofisticação e cores vibrantes. Com um design premium em formato de caixinha de joias, oferece 15 tons inspirados em um buquê floral para criar infinitos looks. Conheça as características desse produto que vão fazer você se apaixonar: 15 cores intensas com acabamentos matte e brilho;Textura aveludada que não esfarela e descarrega cor na primeira aplicação;Fácil de esfumar, permitindo transições suaves e construção de camadas. Esta paleta atende à necessidade de versatilidade na maquiagem, trazendo ativos que garantem alta pigmentação e um resultado de olhar marcante com esfumado impecável. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 159.99, 159.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-823re-mpb4pw0zrq4i07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F23095028577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205467210', 'Eudora Instance Ameixa e Praliné Creme Hidratante Desodorante Corporal 400ml', 'O Creme Hidratante Desodorante Corporal Eudora Instance Ameixa e Praliné envolve sua pele com uma fragrância floriental fascinante, combinando a suculência da ameixa roxa com a indulgência do praliné. Conheça as características desse produto que vão fazer você se apaixonar: - Fórmula com Hydracolageno e Manteiga de Karité; - Hidratação profunda por até 48 horas; - Rápida absorção e toque macio; - Vegano e livre de parabenos. Proporciona sensação de firmeza e pele desodorizada, tornando o cuidado diário um momento inesquecível. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 59.99, 48.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-825zs-mkwpyo3193pib8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58205467210', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203309853', 'Eudora Siàge Cica Therapy Shampoo 250ml', 'O Shampoo Cica Therapy Siàge Eudora possui ativos poderosos que limpa e hidrata profundamente os fios danificados, devolvendo nutrientes e vitalidade a eles desde a sua primeira aplicação. Composto por esqualano e Ômegas 3 e 6, oferece às madeixas menos pontas duplas e 90% menos de fios quebradiços, resultando em mechas mais fortes, mais saudáveis e mais incríveis. Conheça outros destaques deste produto incrível: - Exclusiva Biotecnologia Affinité 4D; - Protege contra ações externas; - Recupera a saúde dos fios; - Cicatriza 100% das áreas danificadas do cabelo; - Produto Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 49.99, 49.99, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mjhpdut8wq2o24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58203309853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297888465', 'Fruteira Natasha 1 Porta 1 Gav.', 'A Fruteira Natasha é perfeita para quem deseja manter a cozinha organizada com praticidade e elegância. Compacta e funcional, ela conta com três cestos metálicos aramados para frutas e legumes, além de uma porta com prateleiras internas e uma gaveta com corrediça metálica, ideais para armazenar utensílios, guardanapos e mantimentos. Diferenciais da Fruteira Natasha: 1 porta com 2 prateleiras internas; 3 cestos metálicos aramados; 1 gaveta com corrediça metálica; Puxadores em PVC cromado; Fabricada em MDP de alta qualidade; Tampo com capacidade de até 20kg; 4 rodízios para fácil movimentação; Acabamento Touch Alto-Relevo ou Alto Brilho UV; Acompanha manual de montagem. Medidas: Altura: 100 cm Largura: 68 cm Profundidade: 37 cm Peso: 21 kg Gaveta: 35,5 cm (largura) x 13,2 cm (altura) x 29,6 cm (profundidade) 📌 Não nos responsabilizamos pela montagem ou instalação. Recomendamos contratar um montador profissional ou serviço especializado de sua preferência. 📷 Imagens meramente ilustrativas.', 309.0, 259.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-m0n40c0mwwas55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842544500%2F23297888465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205399759', 'Copo Térmico Minas 400ml UNITERMI', 'Copo térmico para suas bebidas quentes ou geladas, ideal para café e chá. Graças à tampa com vedação e o bico que abre e fecha, mantém sua bebida na melhor temperatura por pelo menos 1h30, além de facilitar o transporte no dia-a-dia. Características: Capacidade: 400 ml Peso: 0,14 Kg Dimensões: 89,6 x 89,6 x 16,9cm Material: Isolamento em PU (Poliuretano) e demais peças em plástico injetado (PP).', 37.9, 37.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-820m3-mpw827ndwjk029', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719930213%2F58205399759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19147800984', 'Jogo Bate Marshmallow', 'Não derrube o urso! Uma gostosa brincadeira em que derrubar cubos de marshmallow usando um martelinho é uma grande aventura! Você vai martelando e derrubando o piso onde o urso está. Mas muito cuidado! O urso está equilibrado em um grande cubo e quem derrubá-lo perde a chance de ganhar! A partir de 4 anos 2 ou mais jogadores', 109.99, 82.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/984af18e4cb0e12c9aed91191560db01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F19147800984', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998005829', 'Militec-1 200ml ® Condicionador De Metais Para O Seu Carro', 'Atenção: as informações que aparecem na tampa representam o número do lote e a data de envio do produto para o Brasil. A validade é de 5 anos, a partir desta indicação. Além disso, essas informações são importantes para assegurar que o Militec1 é original. Não aceite outro. Vamos às outras informações? Evite que o problema "encoste no seu retrovisor" e use Militec-1. O produto é original, vai lacrado e acompanha adesivo (que indica a data da aplicação) para colar no para-brisas. Importante: Militec-1 não substitui o uso de lubrificantes. Militec-1 é o primeiro e melhor condicionador de metais do mundo. Aumenta a potência do motor, ajuda a economizar combustível e evita manutenção, proporcionando proteção de verdade. Aplicação no motor do carro: Militec-1 pode ser utilizado nos motores a gasolina, álcool, flex, diesel ou GNV de todas as marcas e modelos. Quanto aplicar? Use um frasco de 200 ml para 4 litros de óleo. Quando reaplicar? A cada 20 mil km rodados. Extra: Moto > Você pode utilizar Militec-1 no motor da sua moto, independentemente do modelo e das cilindradas. Existe um frasco exclusivo de 40 ml, que é a dose ideal para motos, com até 1 litro de óleo. E já anota aí essa dica: caso a troca de óleo seja feita a cada 1.000 km, reaplique o Militec-1 a cada 4 trocas. Ar-condicionado > Quando utilizado no ar-condicionado, o Militec-1 reduz o atrito interno do compressor. Isso resulta em economia de combustível, quando o sistema está em uso. A aplicação no sistema leva, em média, 30 minutos e não interfere na carga de gás. 6% do produto sobre o volume de óleo é suficiente para melhorar o desempenho. Nas fotos você encontra mais detalhes sobre outras aplicações do Militec-1. Ainda com dúvida? Nos mande uma mensagem que responderemos o mais rápido possível.', 115.42, 110.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134211-7r98o-m9dpck1ids02ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1449962409%2F20998005829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209543637', 'Kit Bucha + Pivo Bandeja Balança Nissan Tiida / Livina - 6pç', 'DESCRIÇÃO DO PRODUTO: 04 - BUCHA DA BANDEJA (02 - CENTRAL + 02 - PONTA) 02 - PIVO DA BANDEJA APLICAÇÃO: NISSAN TIIDA 2008 EM DIANTE NISSAN LIVINA 2009 EM DIANTE NISSAN GRAND LIVINA 2009 EM DIANTE PRODUTO NOVO, QUALIDADE ORIGINAL. TEMOS MAIS DE 10.000 ITENS EM ESTOQUE, CONFIRA! PEÇA SEU ORÇAMENTO!!! 3 MESES POR DEFEITO DE FABRICAÇÃO.', 296.9, 296.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-820m3-mng63r7jzapx2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1777160589%2F58209543637', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894650300', 'Grandha Bbtox Keratin Complex Reparador Pós Progressiva 480g', 'Grandha Bbtox Keratin Complex 480g NOVA FÓRMULA! O Keratin Complex é ideal para reparar danos causados pelas progressivas, mas também tratar cabelos alisados ou relaxados com ativos legalizados em geral. O kit BBtox Absolute Repair é um poderoso repositor de massa para cabelos fragilizados. Rico em polifenóis de frutas vermelhas, o tratamento BBtox Absolute Repair tem ação altamente antioxidante, hidratando e preenchendo as imperfeições das cutículas. Tratamento capilar profissional de ação restauradora e recuperadora da estrutura capilar que combate os danos causados por procedimentos de "escovas progressivas", reequilibrando o pH dos cabelos e recondicionando a estrutura capilar à manutenção do efeito liso intenso. Potencializando pela ação integrada do ácido hialurônico com variados componentes reconstrutores e polissacarídeos de tamarindo, enorme fonte de polifenóis e rico em fósforo, cálcio e vitaminas A, B e C. Informações Importantes: - Não testado em animais. - Dermatologicamente testado. - Reposição de massa para cabelos fragilizados por "escovas progressivas". Garantia de fábrica: 90 dias', 170.51, 170.51, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-821gg-mgiek97w6tqkb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F22894650300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698459858', 'Sapatênis Masculino Couro Ferracini Confortável Leve Esportivo Original Star Cinza Claro 1056A', 'A linha Star oferece sapatos esportivos com a combinação perfeita de funcionalidade, versatilidade e estilo. Eles são produzidos com sola TR para melhor aderência, forro em tecido e calcanheira em PU para conforto ao caminhar, e cabedal em couro natural para maciez e comodidade. Possuem cadarços elásticos que dispensam amarração, economizando tempo e ainda assim mantendo o estilo intacto. Mais prático, impossível! Sim, claro ou com certeza!? ______________________________________________ FICHA TÉCNICA Cabedal: Couro Palmilha: PU Solado: TR Atacador: Elástico ______________________________________________ - Guia de medidas: (MEDIDAS DA PALMILHA) 37 - 26,5 CM 38 - 27 CM 39 - 27,8 CM 40 - 28,2 CM 41 - 29 CM 42 - 29,2 CM 43 - 30,6 CM 44 - 30,8 CM Se você possui um sapato com a palmilha removível, o processo é bem simples. Pegue uma régua ou uma fita métrica e meça do calcanhar a ponta da palmilha. Com esse número em mãos, basta comparar com a tabela acima.', 359.9, 359.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7qvf2-lg19v2jydgjq1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733934100%2F19698459858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
