INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209719846', 'Refil Desodorante Corporal Natura Luna 100ml', 'Refil Desodorante Natura Luna: Sua Proteção Diária com Fragrância Inspiradora Desfrute da sensação revigorante de bem-estar com o Desodorante Refil Luna. Este Refil Natura foi formulado para garantir proteção duradoura e uma fragrância encantadora, inspirada nos maiores sucessos de nossa perfumaria. Natura Luna Refil combina uma avançada tecnologia desodorante, que auxilia na proteção contra os odores da transpiração, com uma fragrância incrível para arrasar no dia a dia. Além disso, ao optar pelo refil de desodorante, você faz uma escolha mais sustentável e econômica. Garanta frescor e perfumação para todo o corpo com o Refil Desodorante Luna Natura. CARACTERISTICAS: testado dermatologicamente família olfativa: chypre cruelty free vegano DICAS DE USO: Segure a embalagem a 15 centímetros do corpo e da axila e pulverize em abundância. Reaplique ao longo do dia para reforçar a perfumação e ação desodorante.', 44.9, 44.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820oa-mnki5cm1r2tf01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209719846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
