INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698396623', 'Palheta Dianteira Bosch Aerofit HB20 2012-2019', 'Palheta Aerofit limpador de para-brisa dianteiro. Palheta Bosch AEROFIT possui tecnologia para um rendimento eficiente em qualquer condição de tempo. São palhetas com melhor custo benefício do mercado, pois possuem longa vida útil, facilidade de instalação e desempenho aerodinâmico. Suas partes metálicas não estão expostas e com isso ficam livres do desgaste da pintura e corrosão. A borracha possui tratamento de grafite, garantia de uma limpeza mais suave. Especificações Técnicas: - Linha Aerofit; - 16 polegadas (400,00mm) de comprimento; - Aplica do lado do passageiro do veículo. Conteúdo da Embalagem: - 1 unidade linha Aerofit; - Braço/Adaptador para Gancho 9x3, 9x4.', 63.36, 63.36, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reor-m8nfxq3kvuea3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23698396623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
