INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399618728', 'TINTA POLIÉSTER PRATA ETOILE MET 2008 RENAUT 900ML LAZZUDUR', 'TINTA AUTOMOTIVA POLIÉSTER 900ML LAZZUDUR A tinta automotiva à base Poliéster da Lazzuril é indicado para pintura geral, parcial e retoques de veículos automotivos, nacionais e importados, fácil de usar e aplicar. Disponível em sistema mixing machine ( lisas, metálicas e perolizadas). Possui secagem rápida, excelente resistência às intempéries naturais e agentes químicos. Padrão Original Base Poliéster Pronta para Uso Requer aplicação de verniz automotivo após a aplicação da tinta. Conteúdo: 900ML TINTA POLIÉSTER PRATA ETOILE MET 2008 RENAUT 900ML LAZZUDUR', 94.18, 94.18, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rblt-m5kgtz6xuv049a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F18399618728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
