INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19577581208', 'Tênis Olympikus Eros Masculino Feminino Casual Unissex Original', 'Tênis Olympikus Eros Masculino Casual. A Olympikus traz a você o seu mais novo modelo, o EROS Masculino, esse calçado é ideal para o seu dia a dia ou até mesmo naqueles momentos de lazer. Esse calçado vem com o cabedal confeccionado em couro sintético trazendo um visual moderno e estiloso, a parte interna é acolchoada na região do calcanhar e dos dedos, o clip de contraforte é fixo sem muita flexibilidade mantendo o calçado fixo no pé. A entressola é produzida em EVA para trazer mais conforto e amortecimento durante sua jornada, e o seu solado também em EVA antiderrapante garante ótima aderência durante a passada além de trazer um excelente amortecimento. Um excelente calçado para passar aquele final de semana inédito com muito estilo e conforto, garanta já o seu e não fique de fora dessa! Especificações: Cabedal: Sintético. Lingueta: Acolchoada e flexível. Palmilha: Eva garante conforto e fácil higienização. Forro Têxtil: Têxtil acolchoado para maior conforto. Entressola: EVA. Solado: EVA antiderrapante. Ajuste:Cadarço simétrico. Indicação de uso: Casual. Tipo de pisada: Neutra. Dicas de Conservação:Utilizar o calçado conforme a sua modalidade (Running, Casual, Adventure, Society ou Indoor). Dicas de Limpeza:Utilizar um pano levemente umedecido e secar à sombra. Não lavar à máquina, pois poderá destruir ou danificar as fibras do calçado.', 223.89, 223.89, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvn58nctklpi45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764630431%2F19577581208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
