INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19278595470', 'Máscara Capilar de Hidratação HNR NutriSalon 1KG', 'Sobre o produto: Produto profissional. Evita a desidratação dos cabelos. Hidratação prolongada. Indicação: Indicado para todos os tipos de cabelos. Etapa do cronograma capilar: Hidratação Ação: Evita a desidratação dos cabelos. Hidratação prolongada. Ativos: Ácido Hialurônico; Sais minerais e Silicones. Benefícios: Tratamento e Hidratação completa Resultado: Hidratação dos fios. Modo de Uso: Lave duas vezes os cabelos com shampoo, massageando o couro cabeludo em movimentos circulares e enxágue. Separe cerca de 30g do seu HNR Hidratação. Retire o excesso de água com uma toalha, divida os cabelos e inicie a aplicação da máscara no comprimento e pontas enluvando os fios até a última mecha. Potencialize o resultado usando touca térmica deixando agir por 20 minutos. Enxágue.', 118.99, 118.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qvd0-lfpqbpsfr4v665', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F19278595470', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
