INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298799930', 'Protetor de Colchão Solteiro Buddemeyer Maison II Algodão Branco', 'CARACTERÍSTICA DO PRODUTO: Além de serem não alérgicos, são impermeáveis e feitos com o melhor material disponível no mercado mundial. Feitos em malha de algodão, mantém a temperatura da cama bem fresquinha Tecido com toque macio e acabamento de excelente qualidade Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 protetor de colchão 100x200x40cm COMPOSIÇÃO: Tecido da Frente em 100% Algodão, Enchimento e Tecido Lateral em 100% Poliéster, Forro em 100% Poliuretano TIPO DE MATERIAL: Tecido da frente em 100% algodão. Enchimento e tecido lateral em 100% poliéster. Forro em 100% poli DESCRIÇÃO: Protetor de colchão solteiro Maison II. Tecido da frente em 100% algodão. Enchimento e tecido lateral em 100% poliéster. Forro em 100% poliuretano. Para colchão com altura até 40cm. A coleção de protetores Maison II da Buddemeyer oferecem proteção e aconchego para sua cama. Produto não alérgico, impermeável e feito com o melhor material disponível no mercado mundial. Feito em malha de algodão, mantém a temperatura da cama bem fresquinha. Os protetores podem ir à máquina sempre que for necessário, oferecendo a higienização perfeita. Acabamento com elástico para melhor ajuste ao colchão. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 30°C em processo suave. O melhor sabão para manter as características do produto é o de coco ou neutro, não colocar diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Não passar.', 242.0, 199.89, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m9kua88u8i1l2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F21298799930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
