INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18361906048', 'Filtro Combustivel Chevrolet Kadett 89 A 98 Tecfil', 'Aplicação CHEVROLET KADETT GL 2.0 MPFI / EFI 1994 até 1998 KADETT GL/SL/LITE/TURIM 1.8 1989 até 1998 KADETT GLS 1.8 EFI / SL/E 1.8 1989 até 1995 KADETT GLS 2.0 MPFI 1997 até 1998 KADETT GSI / GS 2.0 1989 até 1994 KADETT SPORT 2.0 MPFI / EFI 1995 até 1998 Conteúdo Da Embalagem 1 Filtro de Combustivel Observação Apenas os modelos 8v - GL / GLS / SPORT / EFI / GS Tipo de Veículo para Carros Marca A TECFIL é uma indústria de Filtros Automotivos presente no mercado há mais de 67 anos. A empresa, fundada em 20 de março de 1953, especializou-se no segmento tornando-se a maior fábrica de filtros da América Latina. A Tecfil se dedica a desenvolver filtros de qualidade, sempre buscando o que há de mais moderno em tecnologia e equipamentos para fabricação de seus produtos. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 • Valor unitário EAN 7891342007511 Código do Fabricante GI02/2', 19.25, 19.25, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbn2-llv73im9r80b1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18361906048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
