INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694939047', 'Dual Cheeks Blush Compacto - Hbm03 - Ruby Rose', 'Blush Dual Cheeks Transforme seu visual com o Blush Dual Cheeks, o duo perfeito para um acabamento impecável. Com uma textura leve e macia, este blush garante uma aplicação fácil e uniforme, aderindo bem à pele para um efeito natural e duradouro. Suas cores intensas e versáteis oferecem um toque de cor vibrante, enquanto o acabamento mate evita marcas e manchas indesejadas. Ideal para criar um efeito corado nas maçãs do rosto, o Blush Dual Cheeks é a escolha perfeita para realçar sua beleza. Um duo que combina um rosa choque vibrante com um rosa escuro elegante, oferecendo versatilidade para criar um visual tanto ousado quanto sofisticado. Volumetria: 8,1 Dimensão: 7cm x 7cm Modo de Uso: Aplique o Blush Dual Cheeks nas maçãs do rosto com um pincel, esfumando até obter a intensidade desejada. Para um efeito mais intenso, repita a aplicação. Use as cores separadas ou combine-as para um resultado ainda mais personalizado.', 23.07, 17.78, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-81zv0-mmlzjsvs035xc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784788471%2F22694939047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
