INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12546300545', 'Ducha Portatil Camping Aquecimento Solar Chuveiro Acampament', 'A Ducha Bolsa Camp Shower 20 Litros é a solução ideal para banhos outdoor e perfeita para ocasiões onde não há disponibilidade de energia elétrica. Fabricada em polímero de alta resistência e eficiência, é capaz de aquecer a água do seu banho utilizando apenas o calor do Sol. Seu funcionamento é muito simples, bastando deixá-la exposta ao sol por algumas horas para que absorva a calor dos raios solares, mantendo a água aquecida ainda por vários minutos. Muito segura, possui válvula de fechamento, evitando que a água vaze enquanto aguarda o aquecimento, ou quando não está em uso. Possui "chuveirinho" para o banho e suporte para fixação. Utilize sempre sua Shower Camp fixada acima da altura da cabeça para ter vazão da água. Especificações: Capacidade: 20 litros Válvula ON/OFF Chuveirinho com boa distribuição de água Verso transparente para visualizar o nível da água Temperatura: até 50ºC', 45.0, 45.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8oxmo5w3s3m24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353894917%2F12546300545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
