INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58050663119', 'Ração VetLife Renal para gatos adultos 2,0kg', 'Ração VetLife Renal para gatos adultos 2,0kg Pet: Gatos Idade: Adultos Porte de Raça: Todas Condição: Gatos com problemas renais crônicas e agudas, Tamanho de grão: Específico para todas as raças A Ração VetLife Renal para gatos adultos é um alimento Super Premium desenvolvido para gatos com insuficiências renais crônicas ou agudas, auxiliando contra patologias. A Ração Vetlife garante em sua fórmula uma baixa quantidade de proteínas, sódio e fosforo não contribuindo com a formação e aumento de cálculos, uma ótima quantidade de L-carnitina e ômegas 3 que auxiliam nas funções cardíacas. Por que a Ração VetLife Renal para gatos adultos é um alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendem os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração VetLife Renal para gatos adultos foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Composição da Ração VetLife Renal para gatos adultos Quirera de arroz, ovo em pó, glúten de trigo, farinha de vísceras de aves, farinha de peixe, gordura de frango, óleo de peixe refinado, celulose, DL-metionina, triptofano, L-carnitina, L-lisina, arginina, tirosina, taurina, parede celular de levedura (mannan-oligossacarídeos), fruto-oligossacarídeos, sulfato de condroitina, sulfato de glicosamina, beta caroteno, extrato de Marigold (luteína), hidrolisado de fígado suíno, vitaminas (A, D3, E, K3, B1, B2, B6, B12, C, H, PP, ácido pantotênico, ácido fólico, cloreto de colina), cloreto de potássio, citrato de potássio, carbonato de cálcio, transquelato de ferro, transquelato de cobre, transquelato de zinco, transquelato de manganês, transquelato de selênio, iodato de cálcio, propionato de cálcio, concentrado de tocoferóis.', 237.37, 177.96, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-821do-mgjq82gr6kgb6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F58050663119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209713051', 'Desinfetante Multisuperficies Veja Power Action Lavanda', 'O desinfetante Veja Power Action Lavanda é um produto de limpeza profunda que vai muito além de apenas perfumar o ambiente. Ele é rigorosamente formulado com ativos de alta eficácia que garantem a eliminação de 99,9% das bactérias e fungos, assegurando um ambiente doméstico verdadeiramente higienizado e protegido para toda a família. Sua ação desengordurante facilita a remoção de sujeiras pesadas em diversas superfícies, como pisos, pias, ralos e vasos sanitários. Além do grande poder germicida, ele deixa no ar uma fragrância de lavanda intensa e prolongada, transformando o clima da casa. A embalagem de 1 litro é ideal para o uso frequente em faxinas completas ou manutenções pesadas.', 14.99, 14.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqneky7zk8ozd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58209713051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259703158', 'Cream Cheese Light Danubio', 'O Cream Cheese Light Danubio é a opção ideal para quem busca uma alimentação equilibrada e saborosa. Com menos calorias e sem glúten, é perfeito para dietas com restrição de lactose e para celíacos. * Versão light com redução de 29% de calorias e 35% de gorduras totais * Sem glúten * Ideal para dietas com restrição de lactose * Fabricado por Dan Vigor Indústria e Comércio de Laticínios Ltda', 23.49, 23.49, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqnelghtvrwja3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F58259703158', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259708497', 'Tirolez Mussarela Queijo Fatiado', 'O Queijo Mussarela Fatiado Tirolez é a escolha perfeita para quem busca praticidade e sabor no dia a dia. Produzido com leite de alta qualidade, oferece um sabor suave, textura macia e ótimo derretimento. Ideal para pizzas, sanduíches, lasanhas e diversas outras receitas. Já vem fatiado, pronto para usar! Sem glúten, é uma opção segura para pessoas com restrições alimentares. Com a confiança da marca Tirolez, esse queijo une cremosidade e praticidade em cada pedaço.', 11.49, 10.33, NULL, 'Food & Beverages > Dairy & Eggs > Cheese & Cheese Powder', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqneli7kritc90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259708497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
