INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42415521529', 'Creme Dental Anticárie com Flúor e Cálcio Colgate Tripla Ação 90g 4 unidades', 'O creme dental Colgate Tripla Ação Menta Original proporciona tripla proteção para você e sua família: dentes brancos, protegidos e um hálito refrescante. Benefícios: Sua fórmula com flúor previne as cáries, proporcionando proteção para você e sua família Ajuda a remover as manchas amarelas para manter os seus dentes brancos Possui delicioso sabor de menta, que combate o mau hálito e deixa a sua boca com uma incrível sensação de refrescânciaTripla proteção para você e sua família Embalagem individual de 90g', 35.21, 35.21, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7ratp-mavgg6i26t00ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F42415521529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
