INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42077949271', 'Kit Mini Gotas de Cobertura sabor Chocolate Branco Vegano Zero Açúcar VitaoPRO 100g - 3 Unidades', 'Desfrute da qualidade excepcional das Mini Gotas de Cobertura sabor Chocolate Branco Vegano Zero Açúcar VitaoPRO 100g. Com um sabor equilibrado e envolvente, este chocolate vegano é cuidadosamente elaborado, proporcionando uma experiência única para os apreciadores de chocolate branco, sem adição de açúcar sem lactose e sem glúten. Uma alternativa prática e deliciosa para receitas que respeitam dietas especiais e priorizam qualidade. Desenvolvido para uso profissional no setor de alimentação, o chocolate da Vitao destaca-se por sua versatilidade, sendo uma adição perfeita em diversas receitas, desde confeitaria até sobremesas gourmet. Sua textura cremosa e sabor inconfundível fazem dele uma escolha premium para elevar o padrão das suas criações culinárias de forma mais saudável. Formuladas para resistir ao calor do forno e adicionar qualidade aos seus pratos sem comprometer suas preferências alimentares. vetes. INGREDIENTES: Gordura vegetal, leite de arroz em pó, leite de coco em pó, cúrcuma, edulcorante maltitol, emulsificantes lecitina de soja e poliglicerol polirricinoleato e aromas. ALÉRGICOS: CONTÉM DERIVADO DE SOJA. PODE CONTER AMÊNDOA, AVEIA (SEM GLÚTEN), CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ E AVELÃ. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. SEM GLÚTEN, ZERO ADIÇÃO DE AÇÚCARES, SEM LACTOSE, VEGANO.', 99.89, 93.9, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mje9xdwne1vpd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F42077949271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
