INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093883127', 'Osteo Move Glucosamina 750mg Condroitina 600mg 90cp- PREVENT', 'Osteo Move Glucosamina 750mg + Condroitina 600mg 90 comprimidos - PREVENT Descrição O Osteo Move Glucosamina 750mg + Condroitina 600mg é um suplemento alimentar em 30 comprimidos da Prevent Pharma Princípio ativo: Sulfato de Glucosamina + Sulfato de Condroitina Apresentação: 90 comprimidos Modo de uso Consumir&nbsp;conforme orientação médica. Advertência Este produto não é medicamento. Não exceda a dose indicada. Mantenha fora do alcance de crianças. Gestantes, nutrizes e crianças até 3 anos devem consultar o médico antes do uso. Conservar longe de luz, calor e umidade. Indicado para maiores de 19 anos. NÃO CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. Importante Decoração não inclusa. Imagens ilustrativas. Cores podem variar por luminosidade, monitor ou percepção. Dados fornecidos pelo fabricante/fornecedor.', 98.99, 79.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-m7qzqlwteq3r51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F22093883127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
