INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694023426', 'Boneco Ultraman de 30cm - Superman, O Filme', 'Descrição: A Figura de Ação de 30cm para perfeita para recriar cenas épicas do filme Superman, com pontos de articulação que permitem poses dinâmicas e interações criativas. Ideal para brincadeiras de faz de conta, esta figura estimula a imaginação, o trabalho em equipe e o desenvolvimento de narrativas heroicas, transmitindo valores como coragem e força. As figuras de ação da franquia DC Comics — Superman, Lanterna Verde, Mulher-Gavião e muito mais. É uma excelente opção de presente para fãs de super-heróis e de figuras de ação. Características: Marca: Sunny Brinquedos Referência: 4481 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 30,5 x 10,1 x 5cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Boneco de 30cm Certificado Inmetro: REGISTRO 006748/2021 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 119.99, 112.79, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfh8-m9z0ftzw19927f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F22694023426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898102900', 'Boneco Bart (Fã do Krusty) de 5cm - Os Simpsons', 'Descrição: A nova linha de Simpsons inclui Vovô Simpson, Milhouse, Ralph Wiggum, Cara dos Quadrinhos e Bart. Cada figura apresenta um design altamente detalhado, capturando sua aparência animada. Cada figura possui 4 pontos de articulação para poses dinâmicas e brincadeiras. Compatível com todos os conjuntos de diorama. Colecione toda a gama de figuras e acessórios inspirados nos Simpsons com esta série de figuras. Perfeito para qualquer fã ou colecionador dos Simpsons. Características: Marca: Sunny Brinquedos Referência: 4451 Idade recomendada: A partir de 3 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 14 x 9,5 x 5cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Boneco Certificado Inmetro: REGISTRO 011297/2023 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 89.99, 84.59, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rd50-m7cpvqj2bkdy46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F18898102900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
