INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597733501', 'YDROSOLV FERRO YOSEN COM 30ML', 'Ydrosolv Ferro Yosen Com 30Ml Imunidade Ferro Ydrosolv Ferro Yosen Com 30Ml Imunidade Ferro é um suplemento alimentar desenvolvido para promover benefícios específicos à saúde, com fórmula rica em compostos ativos e nutrientes essenciais. Este produto é indicado para quem busca melhorar o bem-estar físico e mental, fortalecer o sistema imunológico, e complementar a dieta com vitaminas e minerais fundamentais. Composição: Pode conter vitaminas como A, C, D, E, complexo B, minerais como zinco, ferro, magnésio, cálcio, além de ativos como biotina, colágeno, cafeína, cúrcuma, lactulose, entre outros, dependendo da formulação específica. Benefícios: - Fortalecimento do sistema imunológico - Melhora da saúde capilar, da pele e das unhas - Ação antioxidante e anti-inflamatória - Suporte à saúde óssea, muscular e cardiovascular - Mais energia, disposição e foco Indicação: Adultos que desejam complementar a alimentação com nutrientes essenciais, melhorar a qualidade de vida e prevenir deficiências nutricionais. Modo de uso: Ingerir conforme orientação médica ou nutricional. Normalmente, 1 cápsula ou comprimido ao dia, preferencialmente com uma refeição. Informações adicionais: Produto livre de glúten e lactose. Consulte um profissional de saúde antes de iniciar o uso, especialmente em casos de gravidez, lactação ou condições médicas.', 143.21, 143.21, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd68-lwndy7pxob2g57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F21597733501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
