INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392666807', 'Kit 10 Porca Trava Parachoque Corsa Meriva 2002 a 2012 Vectra 97 a 2005 Preto', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Enviamos assim que o pagamento é confirmado. Receba rápido, sem esperar semanas. ⚙️ Para-choque solto, desalinhado ou com folga compromete o visual e a segurança do carro. Este kit com 10 porcas trava resolve o problema de forma simples e definitiva, garantindo fixação firme, acabamento correto e reposição no padrão original. Solução direta, barata e indispensável em manutenções ou reparos de para-choque. 🚗 Compatível com: Chevrolet Corsa 2002 a 2012 Chevrolet Meriva 2002 a 2013 Chevrolet Vectra 1997 a 2005 ℹ️ Mais Informações: Quantidade: 10 porcas trava Aplicação: Fixação do para-choque Cor: Preta Material: Plástico resistente Reposição sob medida Encaixe direto, sem adaptações Ideal para substituir porcas quebradas, ressecadas ou faltantes Produto novo, embalado e protegido 90 dias de garantia e suporte ao cliente para qualquer imprevisto 🏷️ Tags: #porcatravaparachoque #porcaparachoquechevrolet #fixacaoparachoque #kitfixacaoparachoque #porcaplasticaparachoque #reparoparachoque #reposicaoparachoque #parachoquecorsa #parachoquemeriva #parachoquevectra #pecaschevrolet #autopecaschevrolet #manutencaocarro #acabamentoparachoque #fixacaosegura #kyodaiacessorios', 16.32, 14.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mek0md3ms0lcf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F23392666807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992630930', 'Alavanca Abrir Capô Gol 1995 1996 1997 1998 1999 Com puxador', '**Leia com ATENÇÃO todas as informações do anúncio e compre somente na certeza. Verifique o modelo, ano, ou qualquer dúvida nos contate no campo de perguntas antes de finalizar a compra. O custo por eventual devolução será por conta do comprador! ** Produto 1° Linha (NÃO É ORIGINAL) -DESCRIÇÃO: Alavanca Abrir Capô (Com Puxador) -COMPATÍVEL: Volkswagen - Gol G2 1995 a 1999 -ITENS INCLUSOS: 01 - Alavanca Abrir Capô (Com Puxador) -ESPECIFICAÇÕES TÉCNICAS: Com Puxador Fácil Instalação Ideal Para Reposição Acabamento Impecável Alta Resistência e Durabilidade -OBSERVAÇÕES: *Anúncio referente a UNIDADE! *Recomendamos que os produtos sejam instalados por profissionais especializados. *Não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. *Imagem meramente ilustrativa. *Atenção: Não Permitimos a utilização de nossas fotos e/ou vídeos a terceiros. *Não vendemos para PESSOA JURÍDICA fora do ESTADO DE SÃO PAULO. *Caro Cliente! Caso precise devolver o produto, independente do motivo, se atente ao prazo oferecido pela plataforma. Não encerre por conta própria seu pedido de devolução até que o mesmo se resolva! Após o vencimento/encerramento, não poderá mais usufruir dessa cortesia e os custos serão por sua conta.', 38.12, 33.17, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbm0-lo5lilx9sndp93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F22992630930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993060225', 'Kit 3 und Lavitan 50+ com 60 Cpr', 'Lavitan Vitamina 50+ Com 60 Comprimidos é a sua escolha inteligente para manter uma vida ativa e saudável após os 50 anos. Com uma fórmula especialmente desenvolvida para atender às necessidades nutricionais dessa fase da vida, este suplemento é essencial para promover a vitalidade e o bem-estar. Com 60 comprimidos por embalagem, Lavitan Vitamina 50+ é o parceiro ideal na jornada rumo a uma maturidade saudável. Modo De Usar: Tome um comprimido diariamente; Ingira com um copo de água; Idealmente, durante uma refeição; Advertência: Não ultrapasse a dose recomendada; Mantenha fora do alcance das crianças; Consulte um profissional de saúde antes de iniciar qualquer suplemento;', 47.45, 41.99, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rd4v-lw5vnbgnb0vjb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22993060225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41259576172', 'Newpet Caixa de areia autolimpante, colcha automática para gatos aberto controle por aplicativo para vários gatos', '1:Design aberto atualizado: nossa caixa de areia autolimpante tem entrada ampla antiderrapante e estrutura totalmente aberta, garantindo entrada e saída sem esforço para os gatos. Nossa caixa com a parte superior aberta mantém o interior limpo e proporciona um ambiente de proteção e segurança para os gatos., 2:Tecnologia de segurança dupla: 4 sensores ativados por peso + 3 detectores infravermelhos de alta precisão pausam a operação quando o gato está próximo; resposta instantânea à proximidade ou movimento do gato prioriza a segurança., 3:Capacidade de resíduos selados de 10,5 L: o armazenamento de grande capacidade isola os odores de forma eficaz; ideal para uso doméstico por vários dias ou viagens curtas sem manutenção frequente., 4:Compatibilidade com a ninhada: esta caixa de areia automática é otimizada para a maioria das ninhadas de gatos, como bentonita, mineral e ninhadas mistas (não para tofu/cristal), 5:Grande capacidade: o tamanho do tambor de 42 * 41,5 cm pode acomodar gatos com peso superior a 3,3 lb, atendendo às necessidades de lares com vários gatos.O tamanho do tambor de 42*41,5 cm pode acomodar gatos com peso superior a 3,3 lb, atendendo às necessidades de lares com vários gatos', 2498.95, 1395.95, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-mciy3gtz9d8gdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F995716400%2F41259576172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
