INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699303740', 'KIT MOTUL 5100 10W-30 4 LITROS', 'Óleo Motul 5100 10W30 Semissintético 4T Especificações: Aplicação: Lubrificantes para Motor Tipo de motor: 4 Tempos Qualidade: Semissintético Viscosidade: 10W30 Padrão API: API SG/SH/SJ/SL/SM Padrão JASO: JASO MA2 M033MOT111 Technosynthese (Semi-sintético) lubrificante para motos 4 tempos ? Tecnologia Ester Atende as especificações dos fabricantes de motocicletas, especialmente HONDA que recomenda SAE 10W30 visando aumento da economia de combustível. Melhor resistência ao cisalhamento possibilitando troca de marchas suaves. Atende às especificações JASO MA2 para um ótimo desempenho da embreagem úmida. Adequado para catalisadores. * IMPORTANTE - Utilize o campo PERGUNTAS AO VENDEDOR para tirar suas dúvidas. - Antes de comprar, verifique o tamanho/modelo correto. - Para cálculo do frete, digite o CEP para calcular. - Todos os estágios da sua compra será avisado por e-mail. - NÃO ESQUECER de após o recebimento da mercadoria, de dar sua opinião sobre a mercadoria e o vendedor. COMPRA 100% SEGURA Sua compra é garantida pelo . Em caso de extravio ou perda o devolverá o seu pagamento integralmente. Conteúdo 4 Litros', 403.79, 363.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rd4t-lxb7i6zb5bpi9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F18699303740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
