INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210293331', 'Caneta hidrográfica Color''Peps Aqua com 10 cores e 1 Water Brush 844300 Maped', 'Torne-se aprendiz de pintor com as canetas hidrográficas Color&#39;Peps Aqua da Maped! Com 10 canetinhas com ponta de feltro e o pincel de água incluído, as crianças descobrirão uma forma completamente diferente de colorir, enquanto se divertem! Desde desenhar em casa até colorir na escola, essas canetas aquarelável coloridas acompanharão seu filho em todos os lugares! Detalhes: - Ponta de pincel extra macia - 1 caneta Water Brush inclusa - 10 cores - Tinta à base de água', 45.94, 36.9, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-820l5-mnylsmhqyakl40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F916765392%2F58210293331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097497027', 'Kit 2 Fralda Huggies Pants Roupinha Proteção Acolchoada Tamanho M 80 Unidades Descartáveis', 'Fralda Huggies Proteção Acolchoada Pants Tamanho M A Fralda Huggies Proteção Acolchoada Pants Tamanho M, com 80 unidades, é ideal para bebês em fase ativa que precisam de proteção e conforto. Supreme Care Roupinha agora é Proteção Acolchoada: com o mesmo cuidado e proteção de sempre. Abraço confortável para barriguinha e perninhas. Previne marquinhas e oferece até 12 horas de proteção contra vazamentos*. Seu formato tipo roupinha é fácil de vestir e acompanha cada movimento do bebê. Com cintura super macia e melhor proteção de Huggies* é escolha ideal para quem busca conforto, praticidade e segurança em todos os momentos do dia. *Desempenho pode variar conforme hábitos, alimentação e características do bebê. **vs Huggies Rápida Absorção ABSORÇÃO EXTRA*: Nossas fraldas apresentam uma tecnologia de absorção avançada, mantendo seu bebê sequinho por horas (*Mais conforto vs. Huggies Tripla proteção e absorção vs. versão anterior de Huggies Supreme Care sem absorção reforçada); EXTRA PROTEÇÃO DE ATÉ 12 HORAS: As fraldas Huggies têm uma textura que previne a pele delicada do bebê contra assaduras por até 12 horas. Além da maciez, são hipoalergênicas, sem parabenos e fragrâncias, garantindo a segurança do bebê. LIBERDADE DE MOVIMENTO*: A cintura elástica e os canais em X da tecnologia Xtra-Flex garantem movimentos anatômicos. O sistema flexível em cintura, barreiras e orelhas proporciona conforto superior (*Vs. Fraldas Huggies sem a tecnologia Xtra-Flex); ABSORÇÃO ESPECIAL: A tecnologia de rápida absorção de xixi e cocô líquido em segundos previne o contato da pele do bebê e evita reações cutâneas e desconfortos; FÁCIL DE COLOCAR E TIRAR: Nosso sistema simplificado oferece praticidade para os pais, garantindo trocas rápidas e eficientes.', 291.98, 291.98, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mj78s17gk7pj53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21097497027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
