INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299872453', 'Chave de Impacto 1/2" 20V a Bateria Intercambiável Lynus', 'CHAVE DE IMPACTO 1/2" 20V LYNUS – ICLI-20850 A Chave de Impacto a Bateria 20V Lynus ICLI-20850 é ideal para trabalhos pesados e profissionais em borracharias, auto centers, indústrias e manutenção geral. Com torque de 850Nm, permite apertar e soltar parafusos e porcas de M8 a M40 de forma rápida e segura. Compacta, potente e com design ergonômico, oferece máxima praticidade em qualquer ambiente de trabalho. Itens Inclusos 1 Chave de Impacto 1/2" ICLI-20850 1 Bateria 20V 2Ah 1 Carregador Bivolt 1 Manual de instruções Especificações Técnicas Torque máximo: 850Nm Velocidade: variável e reversível Impactos por minuto (IPM): 3200 Encaixe: quadrado 1/2" (13mm) Carcaça: alumínio resistente Bateria: 20V 2Ah intercambiável Carregador: bivolt Por que escolher a Lynus ICLI-20850? Produto novo e original Pronta entrega e envio rápido Compra 100% segura', 781.89, 781.89, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824ih-meoqa63xai9s49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F19299872453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
