INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19375446321', 'Kit livros Aquarela amigas', 'Kit livros Aquarela amigas Loja Oficial Ciranda Cultural Peppa Pig - Brincando com as cores Peppa e sua família passam muitos momentos juntos, passeando ou brincando, dentro ou fora de casa. Muitas vezes, os amigos de Peppa e George também são convidados para participar da diversão. Conheça um pouco mais do universo dessa turma, colorindo o livro com as aquarelas. Editora: Ciranda Cultural Edição: 1, 2018 Autor: Ciranda Cultural Idioma: Português Páginas: 16 Dimensões: L 27.00 x A 28.00 x E 0.10 ISBN: 9788538083306 Coleção: Livro com aquarela Linha Editorial: Licenças Faixa Etária: + 4 anos Assuntos (tags): Atividades, Colorir, Histórias BISAC: Literatura Infantil / Mídia Tie-in Linha de Produto: Aquarela Encadernação: Grampeado Acabamento: Laminação brilho Material: Papel O Show da Luna - De onde vem o arco-íris? Luna, Júpiter e Cláudio vão viver uma experiência colorida para descobrir de onde vem o arco-íris e como ele surge. Embarque nessa aventura, colorindo os desenhos dessa história divertida com a tinta aquarela e o pincel! Editora: Ciranda Cultural Edição: 1, 2017 Autor: Ciranda Cultural Idioma: Português Páginas: 16 Dimensões: L 27.00 x A 28.00 x E 0.10 ISBN: 9788538069140 Coleção: Livro com aquarela Linha Editorial: Licenças Faixa Etária: + 16 anos Assuntos (tags): Curiosidade, Atividades, Colorir BISAC: Literatura Infantil / Mídia Tie-in Linha de Produto: Aquarela Encadernação: Grampeado Acabamento: Laminação brilho Material: Papel Fadas brilhantes Conheça estas lindas fadas e pinte-as como quiser usando a aquarela! Solte a imaginação e dê vida às personagens. Editora: Ciranda Cultural Edição: 1, 2015 Autor: Ciranda Cultural Ilustrador: Sanjay Dhiman Idioma: Português Páginas: 16 Dimensões: L 27.00 x A 28.00 x E 0.20 ISBN: 9788538063841 Coleção: Livro com aquarela Linha Editorial: Ciranda Cultural - Livro-brinquedo Faixa Etária: + 6 anos Assuntos (tags): Colorir, Fadas, Histórias, Diversão, Pintar, Pintura BISAC: Não Ficção Infantil / Arte / Pintura Linha de Produto: Aquarela Encadernação: Grampeado Acabamento: Laminação brilho Material: Papel Moda com as amigas Do calor ao frio, do cinema com as amigas às festas mais incríveis, o importante é manter o estilo, com roupas, acessórios e penteados para todas as ocasiões. Neste livro com aquarela, conheça o closet de Cindy, uma garota fashionista que adora o mundo da moda! Editora: Ciranda Cultural Edição: 1, 2021 Autor: Ieska Tubaldini Labão Ilustrador: Shutterstock Idioma: Português Páginas: 16 Dimensões: L 21.00 x A 28.00 x E 0.20 ISBN: 9786555008364 Coleção: Livro com aquarela Linha Editorial: Ciranda Cultural - Livro-brinquedo Faixa Etária: + 6 anos Assuntos (tags): Colorir, Moda, Atividades, Diversão, Pintura, Pintar BISAC: Jogos & Atividades / Livros de Colorir Linha de Produto: Aquarela Encadernação: Grampeado Acabamento: Laminação brilho Material: Papel', 79.6, 39.8, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-23030-h34m8n8t2fov54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F19375446321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993094187', 'Livro O escriba: Silas', 'Por trás dos homens que moldaram a história, há vários heróis. Silas foi um desses. Grande escriba, registrou grande parte das Escrituras do Novo Testamento como lemos hoje. No estilo clássico de Francine Rivers, a história de Silas permite que os leitores compreendam as Escrituras sob uma luz totalmente nova, de uma perspectiva nunca antes imaginada. Ao longo do caminho, os leitores serão cativados pelo crescimento da igreja primitiva e pelas provações que Paulo sofreu antes de ser martirizado pela causa de Cristo._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2024_x000D_ Autor: Francine Rivers_x000D_ Idioma: Português_x000D_ Páginas: 224_x000D_ Dimensões: L 15.50 x A 22.60 x E 1.31_x000D_ ISBN: 9786550971151_x000D_ Coleção: Filhos da Coragem_x000D_ Linha Editorial: Principis - Literatura cristã_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): Literatura Americana, Estados Unidos, Religiosidade, Velho testamento, Histórias bíblicas, Crença, Direitos autorais_x000D_ BISAC: Ficção / Religiosa_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 44.9, 44.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd64-lwof069gje46dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22993094187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9271106944', 'Coleção Especial Sherlock Holmes - Box com 6 livros - Principis', 'Sherlock Holmes é o investigador mais famoso da literatura. Criação do autor e médico, Sir Arthur Conan Doyle, o personagem utiliza métodos científicos e lógica dedutiva em suas investigações e se tornou um ícone cultural britânico. Os contos de Conan Doyle foram adaptados para rádio e também cinema e se consagrou na cultura popular, influenciando outras obras e impactando o romance policial e as escritas de mistério. Conheça as aventuras de Holmes e seu amigo Dr. Watson com as obras: Um estudo em vermelho, O vale do medo, Aventuras de Sherlock Holmes, Mais aventuras de Sherlock Holmes, O cão dos Baskerville e O signo dos quatro.', 149.9, 74.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/b6849c59d8570cb9e388f5d8a00ee883', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9271106944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
