INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18227997284', 'Chuveiro Ducha Sublime Eletrônica Branco 7500W 220V Zagonel', 'A ducha Eletrônica Sublime é de fácil instalação, que somando design e tecnologia garante funcionalidade e precisão para o melhor banho. Uma ducha com mais conforto em qualquer estação do ano. Possui ajuste progressivo da temperatura ideal para o seu banho, com regulagem segura a distância e com indicação luminosa, exclusiva em LED. O controle de Temperatura é realizado através de uma haste plástica ao alcance das mãos. Uma ducha com muito mais economia de energia elétrica, podendo variar de 40% a 60% ao ano Vantagens: - Fácil instalação: Sistema de engate rápido - Jato obediente, sem gotejamento no uso. - Temperatura progressiva: Ajuste gradual - LED indicador de temperatura - Compatível com sistema de Proteção Diferencial Residual (DR) - Compatível em sistemas de aquecimento Solar e a Gás. -Acionamento com Baixa Pressão de Água (1 M.C.A) - Sistema de proteção contra choque Características Técnicas - Modelo: Sublime - Marca: Zagonel - Cor: Branco - Voltagem: 220v - Corrente Nominal: 34,09 A - Potência: 7500W - Pressão de Funcionamento: 400 kPa (40 m.c.a) - Pressão Mínima para vazão: 10kPa (1 m.c.a) - Grau de Proteção: IP24 - Certificado: ISO 9001 - Disjuntor: 40A (127v) - Fiação: 6mm (127v) - Distância máxima entre disjuntor e aparelho: 30m - Garantia: 12 Meses pelo fabricante - Garantia da resistência: 3 Meses pelo fabricante Informações de consumo kW/h Referencia : 1 banho diário de 8 minutos Mensal mínimo 9,1 kW/h -(Elevação de temperatura de 10ºC – Vazão 3,0L/Min) Mensal míáximo 32,3 kW/h -(Elevação de temperatura de 33ºC – Vazão 3,0L/Min)', 249.9, 218.9, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/6a9d3d0fbc47e60eedef357f30ea6c22', 'https://sh