INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898767231', 'Depilador Britânia BDP04 2 Velocidades 5W Com 4 Acessórios Bivolt', 'Depilador Britânia BDP04 - Conforto e Praticidade na Sua Rotina de Beleza Descubra o Depilador Britânia BDP04 Um aparelho que combina eficiência e versatilidade para garantir a eliminação total dos pelos indesejados. Com 2 velocidades e potência de 5W, ele se adapta às suas necessidades, proporcionando uma depilação suave e eficaz. Os 4 acessórios inclusos oferecem múltiplas opções de uso, tornando o processo de depilação muito mais prático e personalizado. Ideal para quem busca uma solução eficiente e econômica, o Depilador Britânia BDP04 é bivolt, permitindo sua utilização em diferentes locais com facilidade. Seu design ergonômico e leve garante conforto durante o manuseio, enquanto a tecnologia avançada assegura resultados impecáveis. Assim, você pode desfrutar de uma pele lisa e macia com muito mais comodidade. Não perca a chance de potencializar sua rotina de cuidados pessoais! O Depilador Britânia BDP04 é a escolha perfeita para quem valoriza inovação e praticidade na hora da depilação. Adquira já o seu e experimente a transformação que este produto pode trazer à sua beleza e bem-estar! Velocidade: 2 Função: Depilar Resistência à água: Não Uso sem fio: Sim Voltagem: Bivolt Consumo (kWh): 0,0009 Potência (W): 5W Peso (kg): 0.14 Referência: BDP04BIV Dimensões (AxLxP): 110 x 70 x 30cm Registro INMETRO: 064603014 Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Garantia Fabricante: 12 meses', 194.9, 194.9, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-mcwj11t2yyws3e', 'h