INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397993700', 'RELOGIO TEMPERATURA MOTOR 40-110 CABO 6 METROS 60MM', 'RELOGIO TEMPERATURA REDONDO CABO 6 METROS 40º/100º MBB 321/1111/1113/1313/1513/2013/2213/ ADAPTAÇÃO ARO PRETO PRODUTO NOVO MARCA: WILLTEC CÓDIGO FABRICANTE: W01209P Descubra a excelência em peças e acessórios para veículos pesados na RIALAN LITORAL AUTO PEÇAS, a sua principal escolha para garantir qualidade e confiabilidade em cada compra. Com um vasto estoque de mais de 50 mil itens, nossa loja oferece uma extensa variedade de opções para atender às necessidades específicas do seu caminhão. Na RIALAN LITORAL AUTO PEÇAS, comprometemo-nos em fornecer produtos de alta qualidade, garantindo a segurança e a eficiência do seu veículo pesado. Nossa equipe especializada está pronta para ajudar a encontrar as peças certas, oferecendo conhecimento técnico e atendimento personalizado. Além disso, destacamos nossa dedicação à satisfação do cliente, proporcionando uma experiência de compra fácil e transparente. Entendemos a importância de manter seu caminhão em ótimo estado de funcionamento, e é por isso que nos esforçamos para ser a sua escolha número um quando se trata de peças e acessórios automotivos. Não comprometa a performance do seu veículo pesado. Escolha a RIALAN LITORAL AUTO PEÇAS e experimente a diferença que a qualidade faz. Seja para manutenção preventiva ou reparos emergenciais, estamos aqui para oferecer soluções confiáveis e duradouras. Sua satisfação é a nossa prioridade.', 242.0, 242.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ougpejj12x02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1408271217%2F21397993700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593505038', 'Omega 3 - Mega DHA 120 Capsulas 1500mg DHA - Vitafor', 'Experimente o Mega DHA da Vitafor e transforme sua saúde com os benefícios superiores de um produto certificado pelo Programa Internacional de Padrões de Óleo de Peixe (IFOS ™). Com pureza, potência e frescor inigualáveis, este suplemento é uma fonte de Ômega 3 (TG), garantindo maior absorção e conforto gástrico. Extraído de águas frias e profundas de regiões polares, ele oferece ultraconcentração de DHA e EPA, essenciais para o bem-estar. Desfrute de um produto sem odor, com Selo de Qualidade VLabor, que auxilia na redução dos triglicerídeos, melhora a saúde do coração, apoia a saúde mental, reduz a inflamação e aprimora a visão. Sinta a diferença com cada cápsula! Alta Concentração de DHA: Cada cápsula contém uma dose concentrada de DHA, garantindo que você receba uma quantidade ideal desse ácido graxo essencial diariamente. Pureza e Qualidade: Produzido com ingredientes de alta qualidade e submetido a rigorosos controles de pureza, assegurando um produto seguro e eficaz. Fácil de Integrar: Com 120 cápsulas, este suplemento oferece uma solução prática e duradoura para sua suplementação diária. COMPOSIÇÃO: Óleo de peixe. Composição da cápsula: gelatina, água e umectante glicerina. Não contém glúten. Contém peixe Modo de Uso: Consuma duas cápsulas por dia, preferencialmente junto com as refeições, ou conforme orientação de um profissional de saúde. Escolha o Mega DHA da Vitafor para uma abordagem completa e eficaz à sua suplementação diária, promovendo bem-estar e saúde em cada dose.', 275.0, 275.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7req2-m1yg7gxge4n4b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F22593